-- -----------------------------------------------------------------------------
-- Read policies
-- -----------------------------------------------------------------------------
create policy profiles_read on public.profiles for select to authenticated
  using (id = (select auth.uid()) or (select public.is_admin()));

create policy groups_read on public.groups for select to authenticated
  using (
    (select public.is_admin())
    or exists (
      select 1 from public.events e
      where e.group_id = groups.id and public.is_assigned(e.id)
    )
  );

create policy events_read on public.events for select to authenticated
  using ((select public.is_admin()) or public.is_assigned(id));

create policy participants_read on public.participants for select to authenticated
  using (
    (select public.is_admin())
    or (
      is_active and exists (
        select 1 from public.event_participants ep
        where ep.participant_id = participants.id
          and ep.is_active
          and public.is_assigned(ep.event_id)
      )
    )
  );

create policy event_participants_read on public.event_participants for select to authenticated
  using ((select public.is_admin()) or (is_active and public.is_assigned(event_id)));

create policy judge_assignments_read on public.judge_assignments for select to authenticated
  using ((select public.is_admin()) or (judge_id = (select auth.uid()) and is_active));

create policy evaluation_criteria_read on public.evaluation_criteria for select to authenticated
  using ((select public.is_admin()) or public.is_assigned(event_id));

create policy submissions_read on public.submissions for select to authenticated
  using (
    (select public.is_admin())
    or (judge_id = (select auth.uid()) and public.is_assigned(event_id))
  );

create policy criterion_scores_read on public.criterion_scores for select to authenticated
  using ((select public.is_admin()) or public.owns_submission(submission_id));

create policy score_history_read on public.score_history for select to authenticated
  using ((select public.is_admin()));

create policy submission_rounds_read on public.submission_rounds for select to authenticated
  using ((select public.is_admin()) or public.owns_submission(submission_id));

create policy submission_transitions_read on public.submission_transitions for select to authenticated
  using ((select public.is_admin()) or public.owns_submission(submission_id));

create policy reopening_requests_read on public.reopening_requests for select to authenticated
  using ((select public.is_admin()) or public.owns_submission(submission_id));

create policy correction_requests_read on public.correction_requests for select to authenticated
  using ((select public.is_admin()) or public.owns_submission(submission_id));

create policy audit_logs_read on public.audit_logs for select to authenticated
  using ((select public.is_admin()));

create policy tie_resolutions_read on public.tie_resolutions for select to authenticated
  using ((select public.is_admin()));

create policy result_finalizations_read on public.result_finalizations for select to authenticated
  using ((select public.is_admin()));

create policy report_records_read on public.report_records for select to authenticated
  using ((select public.is_admin()));

create policy app_settings_read on public.app_settings for select to authenticated
  using (true);

-- -----------------------------------------------------------------------------
-- Admin write policies (configuration tables only). Consequential changes on
-- these tables are additionally guarded by triggers (workflows migration).
-- -----------------------------------------------------------------------------
create policy groups_admin_insert on public.groups for insert to authenticated
  with check ((select public.is_admin()));
create policy groups_admin_update on public.groups for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
create policy groups_admin_delete on public.groups for delete to authenticated
  using ((select public.is_admin()));

create policy events_admin_insert on public.events for insert to authenticated
  with check ((select public.is_admin()));
create policy events_admin_update on public.events for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
create policy events_admin_delete on public.events for delete to authenticated
  using ((select public.is_admin()));

create policy participants_admin_insert on public.participants for insert to authenticated
  with check ((select public.is_admin()));
create policy participants_admin_update on public.participants for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));

create policy event_participants_admin_insert on public.event_participants for insert to authenticated
  with check ((select public.is_admin()));
create policy event_participants_admin_update on public.event_participants for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));

create policy evaluation_criteria_admin_insert on public.evaluation_criteria for insert to authenticated
  with check ((select public.is_admin()));
create policy evaluation_criteria_admin_update on public.evaluation_criteria for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));
create policy evaluation_criteria_admin_delete on public.evaluation_criteria for delete to authenticated
  using ((select public.is_admin()));

create policy report_records_admin_insert on public.report_records for insert to authenticated
  with check ((select public.is_admin()) and generated_by = (select auth.uid()));
create policy report_records_admin_update on public.report_records for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));

create policy app_settings_admin_update on public.app_settings for update to authenticated
  using ((select public.is_admin())) with check ((select public.is_admin()));

-- -----------------------------------------------------------------------------
-- Table privileges. RLS decides rows; privileges decide which verbs exist.
-- -----------------------------------------------------------------------------
revoke all on all tables in schema public from anon;
revoke all on all sequences in schema public from anon;
revoke all on all tables in schema public from authenticated;
grant select on all tables in schema public to authenticated;
grant insert, update, delete on public.groups, public.events, public.evaluation_criteria
  to authenticated;
grant insert, update on public.participants, public.event_participants, public.report_records
  to authenticated;
grant update on public.app_settings to authenticated;

alter default privileges in schema public revoke all on tables from anon;
alter default privileges in schema public revoke all on sequences from anon;
alter default privileges in schema public revoke execute on functions from anon, public;

revoke execute on all functions in schema public from anon, public;
grant execute on function
  public.is_admin(),
  public.is_active_judge(),
  public.is_assigned(uuid),
  public.owns_submission(uuid),
  public.is_editable_status(public.submission_status)
to authenticated;

-- -----------------------------------------------------------------------------
-- Tamper protection
-- -----------------------------------------------------------------------------
create or replace function public.forbid_modification()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  raise exception 'APPEND_ONLY' using detail = format('%s is append-only', tg_table_name);
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array['audit_logs', 'score_history', 'submission_transitions', 'submission_rounds']
  loop
    execute format(
      'create trigger %I before update or delete on public.%I for each row execute function public.forbid_modification()',
      t || '_append_only', t);
    execute format(
      'create trigger %I before truncate on public.%I for each statement execute function public.forbid_modification()',
      t || '_no_truncate', t);
  end loop;
end;
$$;

-- Roles, usernames and activation can only change through trusted server code
-- (service role) -- never through a user JWT, even an admin's.
create or replace function public.protect_profiles()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if current_user not in ('postgres', 'service_role', 'supabase_admin') then
    raise exception 'PROFILE_CHANGE_FORBIDDEN';
  end if;
  if tg_op = 'UPDATE' and new.id <> old.id then
    raise exception 'PROFILE_CHANGE_FORBIDDEN';
  end if;
  return coalesce(new, old);
end;
$$;

create trigger profiles_protect before insert or update or delete on public.profiles
  for each row execute function public.protect_profiles();

create or replace function public.ensure_assignment_is_judge()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not exists (select 1 from public.profiles where id = new.judge_id and role = 'judge') then
    raise exception 'NOT_A_JUDGE';
  end if;
  return new;
end;
$$;

create trigger judge_assignments_judge_role before insert or update on public.judge_assignments
  for each row execute function public.ensure_assignment_is_judge();

-- ==================== 20261022100200_workflows.sql ====================

-- =============================================================================
-- Workflows (part 1): audit logging, consequential-change guards, finalization
-- invalidation, score integrity and history.
--
-- Error convention: functions raise exceptions whose MESSAGE is a stable code
-- (e.g. SUBMISSION_LOCKED). The app maps codes to translated messages.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Audit
-- -----------------------------------------------------------------------------
create or replace function public.log_audit(
  p_action text,
  p_entity_type text default null,
  p_entity_id uuid default null,
  p_old jsonb default null,
  p_new jsonb default null,
  p_reason text default null,
  p_event_id uuid default null,
  p_group_id uuid default null,
  p_participant_id uuid default null,
  p_judge_id uuid default null,
  p_submission_id uuid default null,
  p_request_id uuid default null,
  p_metadata jsonb default '{}',
  p_actor_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_actor uuid := coalesce(p_actor_id, auth.uid(), nullif(current_setting('app.actor_id', true), '')::uuid);
  v_role text;
begin
  if v_actor is not null then
    select role::text into v_role from public.profiles where id = v_actor;
  end if;
  v_role := coalesce(
    v_role,
    nullif(current_setting('request.jwt.claims', true), '')::jsonb ->> 'role',
    current_user
  );
  insert into public.audit_logs (
    actor_id, actor_role, action, entity_type, entity_id, group_id, event_id,
    participant_id, judge_id, submission_id, request_id, old_value, new_value, reason, metadata
  ) values (
    v_actor, v_role, p_action, p_entity_type, p_entity_id, p_group_id, p_event_id,
    p_participant_id, p_judge_id, p_submission_id, p_request_id, p_old, p_new,
    nullif(btrim(p_reason), ''), coalesce(p_metadata, '{}')
  );
end;
$$;

create or replace function public.current_reason()
returns text
language sql
stable
set search_path = public, pg_temp
as $$
  select nullif(btrim(coalesce(current_setting('app.reason', true), '')), '');
$$;

-- Generic row-change audit for configuration tables.
create or replace function public.audit_row_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old jsonb;
  v_new jsonb;
  v_row jsonb;
begin
  if tg_op in ('UPDATE', 'DELETE') then v_old := to_jsonb(old); end if;
  if tg_op in ('INSERT', 'UPDATE') then v_new := to_jsonb(new); end if;
  if tg_op = 'UPDATE' and (v_old - 'updated_at') = (v_new - 'updated_at') then
    return new;
  end if;
  v_row := coalesce(v_new, v_old);

  perform public.log_audit(
    p_action => tg_table_name || '.' || lower(tg_op),
    p_entity_type => tg_table_name,
    p_entity_id => case when v_row ? 'id' then (v_row ->> 'id')::uuid end,
    p_old => v_old,
    p_new => v_new,
    p_reason => public.current_reason(),
    p_event_id => case when tg_table_name = 'events' then (v_row ->> 'id')::uuid
                       else (v_row ->> 'event_id')::uuid end,
    p_group_id => case when tg_table_name = 'groups' then (v_row ->> 'id')::uuid
                       else (v_row ->> 'group_id')::uuid end,
    p_participant_id => case when tg_table_name = 'participants' then (v_row ->> 'id')::uuid
                             else (v_row ->> 'participant_id')::uuid end,
    p_judge_id => case when tg_table_name = 'profiles' then (v_row ->> 'id')::uuid
                       else (v_row ->> 'judge_id')::uuid end
  );
  return coalesce(new, old);
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array[
    'profiles', 'groups', 'events', 'participants', 'event_participants',
    'judge_assignments', 'evaluation_criteria', 'app_settings'
  ]
  loop
    execute format(
      'create trigger %I after insert or update or delete on public.%I for each row execute function public.audit_row_change()',
      t || '_audit', t);
  end loop;
end;
$$;

-- -----------------------------------------------------------------------------
-- Finalization invalidation (used by triggers and admin functions)
-- -----------------------------------------------------------------------------
create or replace function public.invalidate_finalization_internal(p_event_id uuid, p_reason text)
returns boolean
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  update public.result_finalizations
     set status = 'invalidated',
         invalidated_by = auth.uid(),
         invalidated_at = now(),
         invalidation_reason = p_reason
   where event_id = p_event_id and status = 'active'
  returning id into v_id;
  if v_id is null then
    return false;
  end if;
  perform public.log_audit(
    p_action => 'results.invalidated',
    p_entity_type => 'result_finalization',
    p_entity_id => v_id,
    p_reason => p_reason,
    p_event_id => p_event_id
  );
  return true;
end;
$$;

-- -----------------------------------------------------------------------------
-- Consequential-change guards: once an event has marks, changes that affect
-- scoring need an explicit reason (set by the admin_* functions as app.reason).
-- -----------------------------------------------------------------------------
create or replace function public.event_has_scores(p_event_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select exists (
    select 1 from public.criterion_scores cs
    join public.submissions s on s.id = cs.submission_id
    where s.event_id = p_event_id
  );
$$;

create or replace function public.require_reason(p_what text)
returns void
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if coalesce(char_length(public.current_reason()), 0) < 3 then
    raise exception 'CONFIRMATION_REQUIRED' using detail = p_what;
  end if;
end;
$$;

create or replace function public.guard_criteria_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_event uuid := coalesce(new.event_id, old.event_id);
begin
  if tg_op = 'UPDATE' and new.event_id <> old.event_id then
    if public.event_has_scores(old.event_id) then
      raise exception 'CRITERION_EVENT_CHANGE_FORBIDDEN';
    end if;
  end if;

  if not public.event_has_scores(v_event) then
    return coalesce(new, old);
  end if;

  if tg_op = 'UPDATE' and new.max_marks = old.max_marks and new.is_active = old.is_active then
    -- name / description / order only: no effect on existing marks
    return new;
  end if;

  perform public.require_reason('criteria');

  if tg_op = 'UPDATE' and new.max_marks < old.max_marks and exists (
    select 1 from public.criterion_scores where criterion_id = new.id and value > new.max_marks
  ) then
    raise exception 'MAX_BELOW_EXISTING_SCORE';
  end if;
  return coalesce(new, old);
end;
$$;

create trigger evaluation_criteria_guard before insert or update or delete on public.evaluation_criteria
  for each row execute function public.guard_criteria_change();

create or replace function public.guard_assignment_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'DELETE' then
    if exists (select 1 from public.criterion_scores cs
               join public.submissions s on s.id = cs.submission_id
               where s.event_id = old.event_id and s.judge_id = old.judge_id) then
      raise exception 'ASSIGNMENT_HAS_SCORES';
    end if;
    return old;
  end if;
  if tg_op = 'UPDATE' and (new.event_id <> old.event_id or new.judge_id <> old.judge_id) then
    raise exception 'ASSIGNMENT_IMMUTABLE';
  end if;
  if public.event_has_scores(new.event_id) and (tg_op = 'INSERT' or new.is_active <> old.is_active) then
    perform public.require_reason('assignment');
  end if;
  return new;
end;
$$;

create trigger judge_assignments_guard before insert or update or delete on public.judge_assignments
  for each row execute function public.guard_assignment_change();

create or replace function public.guard_event_participant_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'UPDATE' and (new.event_id <> old.event_id or new.participant_id <> old.participant_id) then
    raise exception 'EVENT_PARTICIPANT_IMMUTABLE';
  end if;
  if public.event_has_scores(new.event_id) and (tg_op = 'INSERT' or new.is_active <> old.is_active) then
    perform public.require_reason('event_participant');
  end if;
  return new;
end;
$$;

create trigger event_participants_guard before insert or update on public.event_participants
  for each row execute function public.guard_event_participant_change();

create or replace function public.guard_participant_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if new.is_active <> old.is_active
     and exists (select 1 from public.criterion_scores where participant_id = new.id) then
    perform public.require_reason('participant');
  end if;
  return new;
end;
$$;

create trigger participants_guard before update on public.participants
  for each row execute function public.guard_participant_change();

create or replace function public.guard_event_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.event_has_scores(old.id) then
    return coalesce(new, old);
  end if;
  if tg_op = 'DELETE' then
    raise exception 'EVENT_HAS_SCORES';
  end if;
  if new.group_id <> old.group_id or new.is_active <> old.is_active
     or new.score_precision <> old.score_precision then
    perform public.require_reason('event');
  end if;
  if new.score_precision < old.score_precision and exists (
    select 1 from public.criterion_scores cs
    join public.submissions s on s.id = cs.submission_id
    where s.event_id = new.id and cs.value <> round(cs.value, new.score_precision)
  ) then
    raise exception 'PRECISION_BELOW_EXISTING_SCORE';
  end if;
  return new;
end;
$$;

create trigger events_guard before update or delete on public.events
  for each row execute function public.guard_event_change();

-- Substantive configuration changes invalidate an existing finalization.
create or replace function public.invalidate_on_config_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_event uuid;
begin
  if tg_table_name = 'evaluation_criteria' then
    if tg_op = 'UPDATE' and new.max_marks = old.max_marks and new.is_active = old.is_active then
      return new;
    end if;
    v_event := coalesce(new.event_id, old.event_id);
  elsif tg_table_name in ('judge_assignments', 'event_participants') then
    if tg_op = 'UPDATE' and new.is_active = old.is_active then
      return new;
    end if;
    v_event := coalesce(new.event_id, old.event_id);
  elsif tg_table_name = 'events' then
    if new.is_active = old.is_active and new.score_precision = old.score_precision then
      return new;
    end if;
    v_event := new.id;
  elsif tg_table_name = 'participants' then
    if new.is_active = old.is_active then
      return new;
    end if;
    for v_event in select event_id from public.event_participants where participant_id = new.id loop
      perform public.invalidate_finalization_internal(
        v_event, format('participants changed: %s', coalesce(public.current_reason(), '-')));
    end loop;
    return new;
  end if;
  perform public.invalidate_finalization_internal(
    v_event, format('%s changed: %s', tg_table_name, coalesce(public.current_reason(), '-')));
  return coalesce(new, old);
end;
$$;

do $$
declare
  t text;
begin
  foreach t in array array['evaluation_criteria', 'judge_assignments', 'event_participants']
  loop
    execute format(
      'create trigger %I after insert or update or delete on public.%I for each row execute function public.invalidate_on_config_change()',
      t || '_invalidate_results', t);
  end loop;
  foreach t in array array['events', 'participants']
  loop
    execute format(
      'create trigger %I after update on public.%I for each row execute function public.invalidate_on_config_change()',
      t || '_invalidate_results', t);
  end loop;
end;
$$;

-- Every assignment gets exactly one submission record.
create or replace function public.ensure_submission_for_assignment()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  insert into public.submissions (event_id, judge_id)
  values (new.event_id, new.judge_id)
  on conflict (event_id, judge_id) do nothing;
  return new;
end;
$$;

create trigger judge_assignments_submission after insert on public.judge_assignments
  for each row execute function public.ensure_submission_for_assignment();

-- -----------------------------------------------------------------------------
-- Score integrity: validation, lock enforcement, history. These run for every
-- write path, including functions, so a lock cannot be bypassed.
-- -----------------------------------------------------------------------------
create or replace function public.validate_score()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
  v_crit public.evaluation_criteria;
  v_precision smallint;
begin
  if tg_op = 'DELETE' then
    raise exception 'SCORE_DELETE_FORBIDDEN';
  end if;
  if tg_op = 'UPDATE' and (new.submission_id <> old.submission_id
       or new.participant_id <> old.participant_id
       or new.criterion_id <> old.criterion_id) then
    raise exception 'SCORE_KEY_IMMUTABLE';
  end if;

  select * into v_sub from public.submissions where id = new.submission_id;
  select * into v_crit from public.evaluation_criteria where id = new.criterion_id;
  if v_crit.event_id is distinct from v_sub.event_id then
    raise exception 'CRITERION_NOT_IN_EVENT';
  end if;
  if not exists (select 1 from public.event_participants
                 where event_id = v_sub.event_id and participant_id = new.participant_id) then
    raise exception 'PARTICIPANT_NOT_IN_EVENT';
  end if;

  if not public.is_editable_status(v_sub.status)
     and coalesce(current_setting('app.admin_override', true), '') <> 'on' then
    raise exception 'SUBMISSION_LOCKED';
  end if;

  if new.value is not null then
    select score_precision into v_precision from public.events where id = v_sub.event_id;
    if new.value < 0 or new.value > v_crit.max_marks then
      raise exception 'OUT_OF_RANGE';
    end if;
    if new.value <> round(new.value, v_precision) then
      raise exception 'PRECISION';
    end if;
  end if;

  if tg_op = 'UPDATE' then
    new.version := case when new.value is distinct from old.value then old.version + 1 else old.version end;
  else
    new.version := 1;
  end if;
  return new;
end;
$$;

create trigger criterion_scores_validate before insert or update or delete on public.criterion_scores
  for each row execute function public.validate_score();

create trigger criterion_scores_no_truncate before truncate on public.criterion_scores
  for each statement execute function public.forbid_modification();

create or replace function public.record_score_history()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_event uuid;
begin
  if tg_op = 'UPDATE' and new.value is not distinct from old.value then
    return new;
  end if;
  insert into public.score_history (
    score_id, submission_id, participant_id, criterion_id,
    old_value, new_value, old_version, new_version, source, reason, changed_by
  ) values (
    new.id, new.submission_id, new.participant_id, new.criterion_id,
    case when tg_op = 'UPDATE' then old.value end, new.value,
    case when tg_op = 'UPDATE' then old.version end, new.version,
    coalesce(nullif(current_setting('app.change_source', true), ''), 'system'),
    public.current_reason(),
    auth.uid()
  );
  select event_id into v_event from public.submissions where id = new.submission_id;
  perform public.invalidate_finalization_internal(
    v_event, format('Score changed: %s', coalesce(public.current_reason(), '-')));
  return new;
end;
$$;

create trigger criterion_scores_history after insert or update on public.criterion_scores
  for each row execute function public.record_score_history();

grant execute on function public.event_has_scores(uuid) to authenticated;

-- ==================== 20261022100300_submissions.sql ====================

-- =============================================================================
-- Workflows (part 2): autosave, final submission, reopening and corrections,
-- admin score correction. All functions lock the submission row (FOR UPDATE),
-- so concurrent saves and submissions are serialised.
-- =============================================================================

create or replace function public.transition_submission(
  p_submission_id uuid,
  p_to public.submission_status,
  p_reason text default null,
  p_request_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_from public.submission_status;
begin
  select status into v_from from public.submissions where id = p_submission_id;
  insert into public.submission_transitions (submission_id, from_status, to_status, actor_id, reason, request_id)
  values (p_submission_id, v_from, p_to, auth.uid(), nullif(btrim(p_reason), ''), p_request_id);
  update public.submissions set status = p_to, version = version + 1 where id = p_submission_id;
end;
$$;

create or replace function public.lock_own_submission(p_submission_id uuid)
returns public.submissions
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
begin
  select * into v_sub from public.submissions where id = p_submission_id for update;
  if not found or v_sub.judge_id is distinct from auth.uid() or not public.is_assigned(v_sub.event_id) then
    raise exception 'NOT_FOUND';
  end if;
  return v_sub;
end;
$$;

create or replace function public.lock_submission_as_admin(p_submission_id uuid)
returns public.submissions
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
begin
  if not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  select * into v_sub from public.submissions where id = p_submission_id for update;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
  return v_sub;
end;
$$;

-- Number of required (participant, criterion) marks still missing.
create or replace function public.submission_missing_count(p_submission_id uuid)
returns integer
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select count(*)::integer
  from public.submissions s
  join public.event_participants ep on ep.event_id = s.event_id and ep.is_active
  join public.participants p on p.id = ep.participant_id and p.is_active
  join public.evaluation_criteria c on c.event_id = s.event_id and c.is_active
  where s.id = p_submission_id
    and (s.judge_id = auth.uid() or public.is_admin())
    and not exists (
      select 1 from public.criterion_scores cs
      where cs.submission_id = s.id and cs.participant_id = ep.participant_id
        and cs.criterion_id = c.id and cs.value is not null
    );
$$;

-- -----------------------------------------------------------------------------
-- Judge autosave.
--   p_changes: [{participant_id, criterion_id, value: number|null, base_version}]
--   base_version = version of the mark the client edited (0 if none).
--   Each change returns status saved | conflict | invalid. A conflict means the
--   server holds a different, newer mark; it is never silently overwritten.
-- -----------------------------------------------------------------------------
create or replace function public.save_scores(p_submission_id uuid, p_changes jsonb)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
  v_change jsonb;
  v_results jsonb := '[]'::jsonb;
  v_changed jsonb := '[]'::jsonb;
  v_participant uuid;
  v_criterion uuid;
  v_value numeric;
  v_base integer;
  v_existing public.criterion_scores;
  v_max numeric;
  v_precision smallint;
  v_new public.criterion_scores;
begin
  if p_changes is null or jsonb_typeof(p_changes) <> 'array' or jsonb_array_length(p_changes) > 1000 then
    raise exception 'INVALID_REQUEST';
  end if;

  v_sub := public.lock_own_submission(p_submission_id);
  if not public.is_editable_status(v_sub.status) then
    raise exception 'SUBMISSION_LOCKED';
  end if;

  select score_precision into v_precision from public.events where id = v_sub.event_id;
  perform set_config('app.change_source', 'judge', true);
  perform set_config('app.reason', '', true);

  for v_change in select value from jsonb_array_elements(p_changes) loop
    begin
      v_participant := (v_change ->> 'participant_id')::uuid;
      v_criterion := (v_change ->> 'criterion_id')::uuid;
      v_base := coalesce((v_change ->> 'base_version')::integer, 0);
      if jsonb_typeof(v_change -> 'value') = 'number' then
        v_value := (v_change ->> 'value')::numeric;
      elsif v_change -> 'value' is null or jsonb_typeof(v_change -> 'value') = 'null' then
        v_value := null;
      else
        raise exception 'bad value';
      end if;
    exception when others then
      v_results := v_results || jsonb_build_object(
        'participant_id', v_change ->> 'participant_id', 'criterion_id', v_change ->> 'criterion_id',
        'status', 'invalid', 'code', 'INVALID_VALUE');
      continue;
    end;

    select max_marks into v_max from public.evaluation_criteria
     where id = v_criterion and event_id = v_sub.event_id and is_active;
    if v_max is null or not exists (
      select 1 from public.event_participants ep
      join public.participants p on p.id = ep.participant_id
      where ep.event_id = v_sub.event_id and ep.participant_id = v_participant
        and ep.is_active and p.is_active
    ) then
      v_results := v_results || jsonb_build_object(
        'participant_id', v_participant, 'criterion_id', v_criterion,
        'status', 'invalid', 'code', 'NOT_IN_EVENT');
      continue;
    end if;

    if v_value is not null and (v_value < 0 or v_value > v_max) then
      v_results := v_results || jsonb_build_object(
        'participant_id', v_participant, 'criterion_id', v_criterion,
        'status', 'invalid', 'code', 'OUT_OF_RANGE');
      continue;
    end if;
    if v_value is not null and v_value <> round(v_value, v_precision) then
      v_results := v_results || jsonb_build_object(
        'participant_id', v_participant, 'criterion_id', v_criterion,
        'status', 'invalid', 'code', 'PRECISION');
      continue;
    end if;

    select * into v_existing from public.criterion_scores
     where submission_id = v_sub.id and participant_id = v_participant and criterion_id = v_criterion
     for update;

    if not found then
      insert into public.criterion_scores (submission_id, participant_id, criterion_id, value, updated_by)
      values (v_sub.id, v_participant, v_criterion, v_value, auth.uid())
      returning * into v_new;
      v_changed := v_changed || jsonb_build_object(
        'participant_id', v_participant, 'criterion_id', v_criterion, 'old', null, 'new', v_value);
      v_results := v_results || jsonb_build_object(
        'participant_id', v_participant, 'criterion_id', v_criterion,
        'status', 'saved', 'value', v_new.value, 'version', v_new.version);
    elsif v_existing.value is not distinct from v_value then
      v_results := v_results || jsonb_build_object(
        'participant_id', v_participant, 'criterion_id', v_criterion,
        'status', 'saved', 'value', v_existing.value, 'version', v_existing.version);
    elsif v_existing.version <> v_base then
      v_results := v_results || jsonb_build_object(
        'participant_id', v_participant, 'criterion_id', v_criterion,
        'status', 'conflict',
        'server_value', v_existing.value,
        'server_version', v_existing.version,
        'server_updated_at', v_existing.updated_at);
    else
      update public.criterion_scores set value = v_value, updated_by = auth.uid()
       where id = v_existing.id
      returning * into v_new;
      v_changed := v_changed || jsonb_build_object(
        'participant_id', v_participant, 'criterion_id', v_criterion,
        'old', v_existing.value, 'new', v_value);
      v_results := v_results || jsonb_build_object(
        'participant_id', v_participant, 'criterion_id', v_criterion,
        'status', 'saved', 'value', v_new.value, 'version', v_new.version);
    end if;
  end loop;

  if jsonb_array_length(v_changed) > 0 then
    if v_sub.status = 'not_started' then
      perform public.transition_submission(v_sub.id, 'in_progress');
    end if;
    update public.submissions set version = version + 1, last_saved_at = now() where id = v_sub.id;
    perform public.log_audit(
      p_action => 'scores.saved', p_entity_type => 'submission', p_entity_id => v_sub.id,
      p_new => v_changed, p_event_id => v_sub.event_id, p_judge_id => v_sub.judge_id,
      p_submission_id => v_sub.id);
  end if;

  select * into v_sub from public.submissions where id = v_sub.id;
  return jsonb_build_object(
    'submission_id', v_sub.id, 'status', v_sub.status, 'version', v_sub.version,
    'last_saved_at', v_sub.last_saved_at, 'results', v_results);
end;
$$;

-- -----------------------------------------------------------------------------
-- Judge final submission
-- -----------------------------------------------------------------------------
create or replace function public.submit_submission(p_submission_id uuid, p_expected_version integer)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
  v_missing integer;
  v_participants integer;
  v_criteria integer;
  v_to public.submission_status;
  v_scores jsonb;
  v_totals jsonb;
begin
  v_sub := public.lock_own_submission(p_submission_id);
  if not public.is_editable_status(v_sub.status) then
    raise exception 'SUBMISSION_LOCKED';
  end if;
  if p_expected_version is not null and v_sub.version <> p_expected_version then
    raise exception 'VERSION_CONFLICT';
  end if;

  select count(*) into v_participants
    from public.event_participants ep
    join public.participants p on p.id = ep.participant_id
   where ep.event_id = v_sub.event_id and ep.is_active and p.is_active;
  select count(*) into v_criteria
    from public.evaluation_criteria where event_id = v_sub.event_id and is_active;
  if v_participants = 0 or v_criteria = 0 then
    raise exception 'NOTHING_TO_SUBMIT';
  end if;

  v_missing := public.submission_missing_count(v_sub.id);
  if v_missing > 0 then
    raise exception 'INCOMPLETE' using detail = v_missing::text;
  end if;

  select coalesce(jsonb_agg(jsonb_build_object(
           'participant_id', cs.participant_id, 'criterion_id', cs.criterion_id,
           'value', cs.value, 'version', cs.version) order by cs.participant_id, cs.criterion_id), '[]'::jsonb)
    into v_scores
    from public.criterion_scores cs
    join public.evaluation_criteria c on c.id = cs.criterion_id and c.is_active
   where cs.submission_id = v_sub.id;

  select coalesce(jsonb_object_agg(t.participant_id, t.total), '{}'::jsonb)
    into v_totals
    from (
      select cs.participant_id, sum(cs.value) as total
      from public.criterion_scores cs
      join public.evaluation_criteria c on c.id = cs.criterion_id and c.is_active
      join public.event_participants ep on ep.event_id = v_sub.event_id
           and ep.participant_id = cs.participant_id and ep.is_active
      where cs.submission_id = v_sub.id
      group by cs.participant_id
    ) t;

  v_to := case when v_sub.round = 0 then 'submitted'::public.submission_status
               else 'resubmitted'::public.submission_status end;

  insert into public.submission_rounds (submission_id, round, status, submitted_by, scores, totals)
  values (v_sub.id, v_sub.round + 1, v_to, auth.uid(), v_scores, v_totals);

  perform public.transition_submission(v_sub.id, v_to);
  update public.submissions
     set round = round + 1, submitted_at = now(), submitted_by = auth.uid()
   where id = v_sub.id
  returning * into v_sub;

  update public.correction_requests
     set status = 'responded', responded_at = coalesce(responded_at, now())
   where submission_id = v_sub.id and status = 'open';

  perform public.log_audit(
    p_action => 'submission.' || v_to::text, p_entity_type => 'submission', p_entity_id => v_sub.id,
    p_new => jsonb_build_object('round', v_sub.round, 'totals', v_totals),
    p_event_id => v_sub.event_id, p_judge_id => v_sub.judge_id, p_submission_id => v_sub.id);

  return jsonb_build_object(
    'submission_id', v_sub.id, 'status', v_sub.status, 'round', v_sub.round,
    'submitted_at', v_sub.submitted_at, 'participant_count', v_participants,
    'criteria_count', v_criteria);
end;
$$;
-- -----------------------------------------------------------------------------
-- Reopening requests
-- -----------------------------------------------------------------------------
create or replace function public.request_reopening(p_submission_id uuid, p_reason text)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
  v_id uuid;
begin
  if p_reason is null or char_length(btrim(p_reason)) < 3 then
    raise exception 'REASON_REQUIRED';
  end if;
  v_sub := public.lock_own_submission(p_submission_id);
  if v_sub.status not in ('submitted', 'resubmitted') then
    raise exception 'INVALID_STATE';
  end if;
  insert into public.reopening_requests (submission_id, requested_by, reason, previous_status)
  values (v_sub.id, auth.uid(), btrim(p_reason), v_sub.status)
  returning id into v_id;
  perform public.transition_submission(v_sub.id, 'reopening_requested', p_reason, v_id);
  perform public.log_audit(
    p_action => 'reopening.requested', p_entity_type => 'reopening_request', p_entity_id => v_id,
    p_reason => p_reason, p_event_id => v_sub.event_id, p_judge_id => v_sub.judge_id,
    p_submission_id => v_sub.id, p_request_id => v_id);
  return v_id;
end;
$$;

create or replace function public.resolve_reopening_request(p_request_id uuid, p_approve boolean, p_note text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_req public.reopening_requests;
  v_sub public.submissions;
begin
  if not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  select * into v_req from public.reopening_requests where id = p_request_id for update;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'INVALID_STATE';
  end if;
  v_sub := public.lock_submission_as_admin(v_req.submission_id);

  update public.reopening_requests
     set status = case when p_approve then 'approved'::public.request_status
                       else 'rejected'::public.request_status end,
         resolved_by = auth.uid(), resolved_at = now(), resolution_note = nullif(btrim(p_note), '')
   where id = v_req.id;

  if p_approve then
    perform public.transition_submission(
      v_sub.id, 'reopened', coalesce(nullif(btrim(p_note), ''), v_req.reason), v_req.id);
    perform public.invalidate_finalization_internal(v_sub.event_id, 'Submission reopened: ' || v_req.reason);
  elsif v_sub.status = 'reopening_requested' then
    perform public.transition_submission(v_sub.id, v_req.previous_status, p_note, v_req.id);
  end if;

  perform public.log_audit(
    p_action => case when p_approve then 'reopening.approved' else 'reopening.rejected' end,
    p_entity_type => 'reopening_request', p_entity_id => v_req.id,
    p_reason => coalesce(nullif(btrim(p_note), ''), v_req.reason),
    p_event_id => v_sub.event_id, p_judge_id => v_sub.judge_id,
    p_submission_id => v_sub.id, p_request_id => v_req.id);
end;
$$;

create or replace function public.admin_reopen_submission(p_submission_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
begin
  if p_reason is null or char_length(btrim(p_reason)) < 3 then
    raise exception 'REASON_REQUIRED';
  end if;
  v_sub := public.lock_submission_as_admin(p_submission_id);
  if v_sub.status not in ('submitted', 'resubmitted', 'reopening_requested') then
    raise exception 'INVALID_STATE';
  end if;
  update public.reopening_requests
     set status = 'approved', resolved_by = auth.uid(), resolved_at = now(),
         resolution_note = 'Reopened by admin: ' || btrim(p_reason)
   where submission_id = v_sub.id and status = 'pending';
  perform public.transition_submission(v_sub.id, 'reopened', p_reason);
  perform public.invalidate_finalization_internal(v_sub.event_id, 'Submission reopened: ' || p_reason);
  perform public.log_audit(
    p_action => 'submission.reopened_by_admin', p_entity_type => 'submission', p_entity_id => v_sub.id,
    p_reason => p_reason, p_event_id => v_sub.event_id, p_judge_id => v_sub.judge_id,
    p_submission_id => v_sub.id);
end;
$$;

-- -----------------------------------------------------------------------------
-- Correction requests
-- -----------------------------------------------------------------------------
create or replace function public.create_correction_request(
  p_submission_id uuid,
  p_participant_id uuid,
  p_criterion_ids uuid[],
  p_message text,
  p_unlock boolean
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
  v_id uuid;
begin
  if p_message is null or char_length(btrim(p_message)) < 3 then
    raise exception 'REASON_REQUIRED';
  end if;
  v_sub := public.lock_submission_as_admin(p_submission_id);
  if p_participant_id is not null and not exists (
    select 1 from public.event_participants
    where event_id = v_sub.event_id and participant_id = p_participant_id
  ) then
    raise exception 'PARTICIPANT_NOT_IN_EVENT';
  end if;
  if exists (
    select 1 from unnest(coalesce(p_criterion_ids, '{}')) cid
    where not exists (select 1 from public.evaluation_criteria c where c.id = cid and c.event_id = v_sub.event_id)
  ) then
    raise exception 'CRITERION_NOT_IN_EVENT';
  end if;

  insert into public.correction_requests (
    submission_id, event_id, participant_id, criterion_ids, message, unlocks_submission, created_by
  ) values (
    v_sub.id, v_sub.event_id, p_participant_id, coalesce(p_criterion_ids, '{}'), btrim(p_message),
    coalesce(p_unlock, false), auth.uid()
  ) returning id into v_id;

  if coalesce(p_unlock, false) and v_sub.status in ('submitted', 'resubmitted', 'reopening_requested') then
    update public.reopening_requests
       set status = 'approved', resolved_by = auth.uid(), resolved_at = now(),
           resolution_note = 'Superseded by correction request'
     where submission_id = v_sub.id and status = 'pending';
    perform public.transition_submission(v_sub.id, 'correction_requested', p_message, v_id);
    perform public.invalidate_finalization_internal(v_sub.event_id, 'Correction requested: ' || p_message);
  end if;

  perform public.log_audit(
    p_action => 'correction.requested', p_entity_type => 'correction_request', p_entity_id => v_id,
    p_new => jsonb_build_object('criterion_ids', p_criterion_ids, 'unlock', p_unlock),
    p_reason => p_message, p_event_id => v_sub.event_id, p_participant_id => p_participant_id,
    p_judge_id => v_sub.judge_id, p_submission_id => v_sub.id, p_request_id => v_id);
  return v_id;
end;
$$;

create or replace function public.respond_correction_request(p_request_id uuid, p_response text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_req public.correction_requests;
  v_sub public.submissions;
begin
  if p_response is null or char_length(btrim(p_response)) < 1 then
    raise exception 'REASON_REQUIRED';
  end if;
  select * into v_req from public.correction_requests where id = p_request_id for update;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
  v_sub := public.lock_own_submission(v_req.submission_id);
  if v_req.status not in ('open', 'responded') then
    raise exception 'INVALID_STATE';
  end if;
  update public.correction_requests
     set judge_response = btrim(p_response), responded_at = now(), status = 'responded'
   where id = v_req.id;
  perform public.log_audit(
    p_action => 'correction.responded', p_entity_type => 'correction_request', p_entity_id => v_req.id,
    p_new => jsonb_build_object('response', btrim(p_response)),
    p_event_id => v_sub.event_id, p_participant_id => v_req.participant_id,
    p_judge_id => v_sub.judge_id, p_submission_id => v_sub.id, p_request_id => v_req.id);
end;
$$;

create or replace function public.resolve_correction_request(p_request_id uuid, p_note text, p_cancel boolean)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_req public.correction_requests;
begin
  if not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  select * into v_req from public.correction_requests where id = p_request_id for update;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
  if v_req.status in ('resolved', 'cancelled') then
    raise exception 'INVALID_STATE';
  end if;
  update public.correction_requests
     set status = case when p_cancel then 'cancelled'::public.correction_status
                       else 'resolved'::public.correction_status end,
         resolved_by = auth.uid(), resolved_at = now(), resolution_note = nullif(btrim(p_note), '')
   where id = v_req.id;
  perform public.log_audit(
    p_action => case when p_cancel then 'correction.cancelled' else 'correction.resolved' end,
    p_entity_type => 'correction_request', p_entity_id => v_req.id, p_reason => p_note,
    p_event_id => v_req.event_id, p_participant_id => v_req.participant_id,
    p_submission_id => v_req.submission_id, p_request_id => v_req.id);
end;
$$;

-- -----------------------------------------------------------------------------
-- Admin score correction: mandatory reason, audited, submission stays locked,
-- any finalization of the event is invalidated (score trigger).
-- -----------------------------------------------------------------------------
create or replace function public.admin_set_score(
  p_submission_id uuid,
  p_participant_id uuid,
  p_criterion_id uuid,
  p_value numeric,
  p_reason text
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
  v_old numeric;
  v_new public.criterion_scores;
begin
  if p_reason is null or char_length(btrim(p_reason)) < 3 then
    raise exception 'REASON_REQUIRED';
  end if;
  v_sub := public.lock_submission_as_admin(p_submission_id);

  perform set_config('app.admin_override', 'on', true);
  perform set_config('app.change_source', 'admin', true);
  perform set_config('app.reason', btrim(p_reason), true);

  select value into v_old from public.criterion_scores
   where submission_id = v_sub.id and participant_id = p_participant_id and criterion_id = p_criterion_id
   for update;

  insert into public.criterion_scores (submission_id, participant_id, criterion_id, value, updated_by)
  values (v_sub.id, p_participant_id, p_criterion_id, p_value, auth.uid())
  on conflict (submission_id, participant_id, criterion_id)
  do update set value = excluded.value, updated_by = excluded.updated_by
  returning * into v_new;

  update public.submissions set version = version + 1, last_saved_at = now() where id = v_sub.id;
  perform set_config('app.admin_override', '', true);

  perform public.log_audit(
    p_action => 'score.admin_corrected', p_entity_type => 'criterion_score', p_entity_id => v_new.id,
    p_old => jsonb_build_object('value', v_old), p_new => jsonb_build_object('value', v_new.value),
    p_reason => p_reason, p_event_id => v_sub.event_id, p_participant_id => p_participant_id,
    p_judge_id => v_sub.judge_id, p_submission_id => v_sub.id,
    p_metadata => jsonb_build_object('criterion_id', p_criterion_id));
  return jsonb_build_object('value', v_new.value, 'version', v_new.version);
end;
$$;

grant execute on function
  public.save_scores(uuid, jsonb),
  public.submit_submission(uuid, integer),
  public.request_reopening(uuid, text),
  public.resolve_reopening_request(uuid, boolean, text),
  public.admin_reopen_submission(uuid, text),
  public.create_correction_request(uuid, uuid, uuid[], text, boolean),
  public.respond_correction_request(uuid, text),
  public.resolve_correction_request(uuid, text, boolean),
  public.admin_set_score(uuid, uuid, uuid, numeric, text),
  public.submission_missing_count(uuid)
to authenticated;

-- ==================== 20261022100400_results.sql ====================

-- =============================================================================
-- Results: aggregation, ranking, tie handling, finalization, progress overview.
--
-- Aggregation rule: a participant's aggregate is the SUM of the totals awarded
-- by every *required* judge (active assignment, active judge). A judge's total
-- is the sum of that judge's marks over the event's active criteria.
-- Results are only computed once every required judge has submitted a
-- complete submission. Ties are never broken automatically.
-- =============================================================================

create or replace function public.missing_count_internal(p_submission_id uuid)
returns integer
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select count(*)::integer
  from public.submissions s
  join public.event_participants ep on ep.event_id = s.event_id and ep.is_active
  join public.participants p on p.id = ep.participant_id and p.is_active
  join public.evaluation_criteria c on c.event_id = s.event_id and c.is_active
  where s.id = p_submission_id
    and not exists (
      select 1 from public.criterion_scores cs
      where cs.submission_id = s.id and cs.participant_id = ep.participant_id
        and cs.criterion_id = c.id and cs.value is not null
    );
$$;

create or replace function public.event_results_internal(p_event_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_required integer;
  v_submitted integer;
  v_incomplete integer;
  v_judges jsonb;
  v_criteria jsonb;
  v_max_per_judge numeric;
  v_participant_count integer;
  v_rows jsonb;
  v_ties jsonb := '[]'::jsonb;
  v_rank_map jsonb := '{}'::jsonb;
  v_unresolved integer := 0;
  v_tie record;
  v_res public.tie_resolutions;
  v_final public.result_finalizations;
  v_complete boolean;
  v_status text;
begin
  with req as (
    select a.judge_id, p.display_name, p.username, s.id as submission_id, s.status, s.submitted_at,
           case when s.status in ('submitted', 'resubmitted')
                then public.missing_count_internal(s.id) end as missing
    from public.judge_assignments a
    join public.profiles p on p.id = a.judge_id and p.is_active and p.role = 'judge'
    left join public.submissions s on s.event_id = a.event_id and s.judge_id = a.judge_id
    where a.event_id = p_event_id and a.is_active
  )
  select count(*),
         count(*) filter (where status in ('submitted', 'resubmitted')),
         count(*) filter (where status in ('submitted', 'resubmitted') and missing > 0),
         coalesce(jsonb_agg(jsonb_build_object(
           'judge_id', judge_id, 'display_name', display_name, 'username', username,
           'submission_id', submission_id, 'status', status, 'submitted_at', submitted_at,
           'missing', missing) order by username), '[]'::jsonb)
    into v_required, v_submitted, v_incomplete, v_judges
    from req;

  select coalesce(jsonb_agg(jsonb_build_object(
           'id', id, 'name', name, 'max_marks', max_marks, 'display_order', display_order)
           order by display_order, name), '[]'::jsonb),
         coalesce(sum(max_marks), 0)
    into v_criteria, v_max_per_judge
    from public.evaluation_criteria where event_id = p_event_id and is_active;

  select count(*) into v_participant_count
    from public.event_participants ep
    join public.participants p on p.id = ep.participant_id and p.is_active
   where ep.event_id = p_event_id and ep.is_active;

  select * into v_final from public.result_finalizations
   where event_id = p_event_id and status = 'active';

  v_complete := v_required > 0 and v_submitted = v_required and v_incomplete = 0
                and v_participant_count > 0 and jsonb_array_length(v_criteria) > 0;

  if not v_complete then
    return jsonb_build_object(
      'event_id', p_event_id, 'status', 'judging_in_progress', 'complete', false,
      'required_judges', v_required, 'submitted_judges', v_submitted,
      'incomplete_submissions', v_incomplete, 'judges', v_judges, 'criteria', v_criteria,
      'max_per_judge', v_max_per_judge, 'participant_count', v_participant_count,
      'participants', null, 'ties', '[]'::jsonb, 'unresolved_ties', 0,
      'finalization', null);
  end if;

  with req as (
    select s.id as submission_id, s.judge_id
    from public.judge_assignments a
    join public.profiles p on p.id = a.judge_id and p.is_active and p.role = 'judge'
    join public.submissions s on s.event_id = a.event_id and s.judge_id = a.judge_id
    where a.event_id = p_event_id and a.is_active
  ),
  ep as (
    select p.id as participant_id, p.code, p.name, p.affiliation, p.kind
    from public.event_participants e
    join public.participants p on p.id = e.participant_id and p.is_active
    where e.event_id = p_event_id and e.is_active
  ),
  totals as (
    select r.judge_id, cs.participant_id, sum(cs.value) as total
    from public.criterion_scores cs
    join req r on r.submission_id = cs.submission_id
    join public.evaluation_criteria c on c.id = cs.criterion_id and c.is_active
    group by r.judge_id, cs.participant_id
  ),
  agg as (
    select ep.participant_id, ep.code, ep.name, ep.affiliation, ep.kind,
           coalesce(sum(t.total), 0) as aggregate,
           coalesce(jsonb_object_agg(t.judge_id, t.total) filter (where t.judge_id is not null), '{}'::jsonb) as judge_totals
    from ep left join totals t on t.participant_id = ep.participant_id
    group by ep.participant_id, ep.code, ep.name, ep.affiliation, ep.kind
  ),
  ranked as (
    select agg.*,
           rank() over (order by aggregate desc)::integer as calc_rank,
           count(*) over (partition by aggregate)::integer as tie_size
    from agg
  )
  select jsonb_agg(jsonb_build_object(
           'participant_id', participant_id, 'code', code, 'name', name,
           'affiliation', affiliation, 'kind', kind, 'aggregate', aggregate,
           'judge_totals', judge_totals, 'calc_rank', calc_rank, 'tie_size', tie_size)
           order by aggregate desc, code)
    into v_rows
    from ranked;

  for v_tie in
    select (x ->> 'aggregate')::numeric as aggregate,
           array_agg((x ->> 'participant_id')::uuid order by (x ->> 'participant_id')::uuid) as ids,
           min((x ->> 'calc_rank')::integer) as start_rank
    from jsonb_array_elements(v_rows) x
    where (x ->> 'tie_size')::integer > 1
    group by (x ->> 'aggregate')::numeric
    order by 1 desc
  loop
    v_res := null;
    select * into v_res from public.tie_resolutions
     where event_id = p_event_id and is_active
       and aggregate = v_tie.aggregate and participant_ids = v_tie.ids
     order by resolved_at desc limit 1;
    v_ties := v_ties || jsonb_build_object(
      'aggregate', v_tie.aggregate, 'participant_ids', to_jsonb(v_tie.ids),
      'start_rank', v_tie.start_rank, 'resolved', v_res.id is not null,
      'resolution_id', v_res.id, 'ranks', v_res.ranks, 'reason', v_res.reason,
      'resolved_at', v_res.resolved_at);
    if v_res.id is null then
      v_unresolved := v_unresolved + 1;
    else
      v_rank_map := v_rank_map || v_res.ranks;
    end if;
  end loop;

  select jsonb_agg(y.row order by coalesce((y.row ->> 'final_rank')::integer, (y.row ->> 'calc_rank')::integer),
                   (y.row ->> 'aggregate')::numeric desc, y.row ->> 'code')
    into v_rows
    from (
      select x || jsonb_build_object(
               'tied', (x ->> 'tie_size')::integer > 1,
               'final_rank', case when (x ->> 'tie_size')::integer = 1 then (x ->> 'calc_rank')::integer
                                  else (v_rank_map ->> (x ->> 'participant_id'))::integer end) as row
      from jsonb_array_elements(v_rows) x
    ) y;

  v_status := case
    when v_final.id is not null then 'finalized'
    when v_unresolved > 0 then 'awaiting_tie_resolution'
    else 'ready_for_finalization' end;

  return jsonb_build_object(
    'event_id', p_event_id, 'status', v_status, 'complete', true,
    'required_judges', v_required, 'submitted_judges', v_submitted,
    'incomplete_submissions', v_incomplete, 'judges', v_judges, 'criteria', v_criteria,
    'max_per_judge', v_max_per_judge, 'participant_count', v_participant_count,
    'participants', v_rows, 'ties', v_ties, 'unresolved_ties', v_unresolved,
    'finalization', case when v_final.id is null then null else jsonb_build_object(
      'id', v_final.id, 'finalized_at', v_final.finalized_at, 'finalized_by', v_final.finalized_by) end);
end;
$$;

create or replace function public.get_event_results(p_event_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  return public.event_results_internal(p_event_id);
end;
$$;

-- -----------------------------------------------------------------------------
-- Tie resolution. p_ranks: {"<participant_id>": rank, ...}. Ranks must lie in
-- [start_rank, start_rank + n - 1] and the best rank must equal start_rank.
-- Equal ranks are allowed (shared place) when the admin decides so.
-- -----------------------------------------------------------------------------
create or replace function public.resolve_tie(
  p_event_id uuid,
  p_participant_ids uuid[],
  p_ranks jsonb,
  p_reason text,
  p_related_correction_ids uuid[] default '{}'
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_results jsonb;
  v_tie jsonb;
  v_ids uuid[];
  v_start integer;
  v_n integer;
  v_rank integer;
  v_min integer := null;
  v_pid uuid;
  v_id uuid;
  v_original jsonb;
begin
  if not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  if p_reason is null or char_length(btrim(p_reason)) < 3 then
    raise exception 'REASON_REQUIRED';
  end if;
  perform 1 from public.events where id = p_event_id for update;

  v_results := public.event_results_internal(p_event_id);
  if v_results ->> 'status' = 'finalized' then
    raise exception 'ALREADY_FINALIZED';
  end if;
  if not (v_results ->> 'complete')::boolean then
    raise exception 'NOT_COMPLETE';
  end if;

  select array_agg(x order by x) into v_ids from unnest(p_participant_ids) x;
  select t into v_tie from jsonb_array_elements(v_results -> 'ties') t
   where (select array_agg(e::uuid order by e::uuid) from jsonb_array_elements_text(t -> 'participant_ids') e) = v_ids;
  if v_tie is null then
    raise exception 'TIE_NOT_FOUND';
  end if;

  v_start := (v_tie ->> 'start_rank')::integer;
  v_n := array_length(v_ids, 1);
  if (select count(*) from jsonb_object_keys(p_ranks)) <> v_n then
    raise exception 'INVALID_RANKS';
  end if;
  foreach v_pid in array v_ids loop
    if not (p_ranks ? v_pid::text) or jsonb_typeof(p_ranks -> v_pid::text) <> 'number' then
      raise exception 'INVALID_RANKS';
    end if;
    v_rank := (p_ranks ->> v_pid::text)::integer;
    if v_rank::numeric <> (p_ranks ->> v_pid::text)::numeric or v_rank < v_start or v_rank > v_start + v_n - 1 then
      raise exception 'INVALID_RANKS';
    end if;
    v_min := least(coalesce(v_min, v_rank), v_rank);
  end loop;
  if v_min <> v_start then
    raise exception 'INVALID_RANKS';
  end if;

  select jsonb_agg(p) into v_original from jsonb_array_elements(v_results -> 'participants') p
   where (p ->> 'participant_id')::uuid = any (v_ids);

  update public.tie_resolutions set is_active = false
   where event_id = p_event_id and is_active and participant_ids = v_ids;

  insert into public.tie_resolutions (
    event_id, aggregate, participant_ids, original, ranks, reason, related_correction_ids, resolved_by
  ) values (
    p_event_id, (v_tie ->> 'aggregate')::numeric, v_ids, v_original, p_ranks, btrim(p_reason),
    coalesce(p_related_correction_ids, '{}'), auth.uid()
  ) returning id into v_id;

  perform public.log_audit(
    p_action => 'tie.resolved', p_entity_type => 'tie_resolution', p_entity_id => v_id,
    p_old => v_original, p_new => p_ranks, p_reason => p_reason, p_event_id => p_event_id,
    p_metadata => jsonb_build_object('aggregate', v_tie -> 'aggregate', 'start_rank', v_start));
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Finalization: stores an immutable snapshot used by reports.
-- -----------------------------------------------------------------------------
create or replace function public.finalize_event_results(p_event_id uuid)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_results jsonb;
  v_event jsonb;
  v_breakdown jsonb;
  v_id uuid;
begin
  if not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  perform 1 from public.events where id = p_event_id for update;

  v_results := public.event_results_internal(p_event_id);
  if v_results ->> 'status' = 'finalized' then
    raise exception 'ALREADY_FINALIZED';
  end if;
  if v_results ->> 'status' <> 'ready_for_finalization' then
    raise exception 'NOT_READY' using detail = v_results ->> 'status';
  end if;

  select jsonb_build_object(
           'id', e.id, 'code', e.code, 'name', e.name,
           'group', jsonb_build_object('id', g.id, 'code', g.code, 'name', g.name))
    into v_event
    from public.events e join public.groups g on g.id = e.group_id
   where e.id = p_event_id;

  select coalesce(jsonb_agg(jsonb_build_object(
           'judge_id', s.judge_id, 'participant_id', cs.participant_id,
           'criterion_id', cs.criterion_id, 'value', cs.value)), '[]'::jsonb)
    into v_breakdown
    from public.criterion_scores cs
    join public.submissions s on s.id = cs.submission_id
    join public.judge_assignments a on a.event_id = s.event_id and a.judge_id = s.judge_id and a.is_active
    join public.profiles p on p.id = s.judge_id and p.is_active
    join public.evaluation_criteria c on c.id = cs.criterion_id and c.is_active
    join public.event_participants ep on ep.event_id = s.event_id and ep.participant_id = cs.participant_id and ep.is_active
   where s.event_id = p_event_id;

  insert into public.result_finalizations (event_id, snapshot, finalized_by)
  values (
    p_event_id,
    v_results || jsonb_build_object('event', v_event, 'breakdown', v_breakdown, 'status', 'finalized'),
    auth.uid()
  ) returning id into v_id;

  perform public.log_audit(
    p_action => 'results.finalized', p_entity_type => 'result_finalization', p_entity_id => v_id,
    p_new => jsonb_build_object('participants', v_results -> 'participants', 'ties', v_results -> 'ties'),
    p_event_id => p_event_id);
  return v_id;
end;
$$;

create or replace function public.unfinalize_event_results(p_event_id uuid, p_reason text)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  if p_reason is null or char_length(btrim(p_reason)) < 3 then
    raise exception 'REASON_REQUIRED';
  end if;
  if not public.invalidate_finalization_internal(p_event_id, btrim(p_reason)) then
    raise exception 'NOT_FINALIZED';
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Admin dashboard: per-event progress (no marks, no rankings).
-- -----------------------------------------------------------------------------
create or replace function public.admin_event_progress()
returns table (
  event_id uuid,
  event_code text,
  event_name text,
  event_active boolean,
  event_order integer,
  group_id uuid,
  group_code text,
  group_name text,
  group_order integer,
  participant_count integer,
  criteria_count integer,
  required_judges integer,
  submitted integer,
  in_progress integer,
  not_started integer,
  incomplete_submissions integer,
  reopening_pending integer,
  corrections_open integer,
  finalized boolean
)
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
  return query
  select e.id, e.code, e.name, e.is_active, e.display_order,
         g.id, g.code, g.name, g.display_order,
         (select count(*)::integer from public.event_participants ep
            join public.participants p on p.id = ep.participant_id and p.is_active
           where ep.event_id = e.id and ep.is_active),
         (select count(*)::integer from public.evaluation_criteria c where c.event_id = e.id and c.is_active),
         coalesce(st.required, 0), coalesce(st.submitted, 0), coalesce(st.in_progress, 0),
         coalesce(st.not_started, 0), coalesce(st.incomplete, 0),
         (select count(*)::integer from public.reopening_requests r
            join public.submissions s on s.id = r.submission_id
           where s.event_id = e.id and r.status = 'pending'),
         (select count(*)::integer from public.correction_requests cr
           where cr.event_id = e.id and cr.status in ('open', 'responded')),
         exists (select 1 from public.result_finalizations f where f.event_id = e.id and f.status = 'active')
  from public.events e
  join public.groups g on g.id = e.group_id
  left join lateral (
    select count(*)::integer as required,
           count(*) filter (where s.status in ('submitted', 'resubmitted'))::integer as submitted,
           count(*) filter (where s.status in ('in_progress', 'reopened', 'correction_requested', 'reopening_requested'))::integer as in_progress,
           count(*) filter (where s.status = 'not_started' or s.status is null)::integer as not_started,
           count(*) filter (where s.status in ('submitted', 'resubmitted') and public.missing_count_internal(s.id) > 0)::integer as incomplete
    from public.judge_assignments a
    join public.profiles pr on pr.id = a.judge_id and pr.is_active and pr.role = 'judge'
    left join public.submissions s on s.event_id = a.event_id and s.judge_id = a.judge_id
    where a.event_id = e.id and a.is_active
  ) st on true
  order by g.display_order, g.name, e.display_order, e.name;
end;
$$;

grant execute on function
  public.get_event_results(uuid),
  public.resolve_tie(uuid, uuid[], jsonb, text, uuid[]),
  public.finalize_event_results(uuid),
  public.unfinalize_event_results(uuid, text),
  public.admin_event_progress()
to authenticated;

-- ==================== 20261022100500_admin_ops.sql ====================

-- =============================================================================
-- Admin operations. Each sets app.reason (when given) so the change guards and
-- audit triggers record why a consequential change was made.
-- =============================================================================

create or replace function public.assert_admin()
returns void
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
begin
  if not public.is_admin() then
    raise exception 'FORBIDDEN';
  end if;
end;
$$;

create or replace function public.apply_reason(p_reason text)
returns void
language plpgsql
set search_path = public, pg_temp
as $$
begin
  perform set_config('app.reason', coalesce(btrim(p_reason), ''), true);
end;
$$;

-- -----------------------------------------------------------------------------
-- Assignments
-- -----------------------------------------------------------------------------
create or replace function public.admin_set_assignment(
  p_event_id uuid, p_judge_id uuid, p_active boolean, p_reason text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  perform public.assert_admin();
  perform public.apply_reason(p_reason);
  insert into public.judge_assignments (event_id, judge_id, is_active, created_by)
  values (p_event_id, p_judge_id, p_active, auth.uid())
  on conflict (event_id, judge_id) do update set is_active = excluded.is_active
  returning id into v_id;
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Events
-- -----------------------------------------------------------------------------
create or replace function public.admin_save_event(
  p_id uuid,
  p_group_id uuid,
  p_code text,
  p_name text,
  p_description text,
  p_instructions text,
  p_score_precision smallint,
  p_display_order integer,
  p_is_active boolean,
  p_reason text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  perform public.assert_admin();
  perform public.apply_reason(p_reason);
  if p_id is null then
    insert into public.events (group_id, code, name, description, instructions, score_precision, display_order, is_active)
    values (p_group_id, lower(btrim(p_code)), btrim(p_name), nullif(btrim(p_description), ''),
            nullif(btrim(p_instructions), ''), p_score_precision, coalesce(p_display_order, 0), coalesce(p_is_active, true))
    returning id into v_id;
  else
    update public.events
       set group_id = p_group_id, code = lower(btrim(p_code)), name = btrim(p_name),
           description = nullif(btrim(p_description), ''), instructions = nullif(btrim(p_instructions), ''),
           score_precision = p_score_precision, display_order = coalesce(p_display_order, 0),
           is_active = coalesce(p_is_active, true)
     where id = p_id
    returning id into v_id;
    if v_id is null then
      raise exception 'NOT_FOUND';
    end if;
  end if;
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Criteria
-- -----------------------------------------------------------------------------
create or replace function public.admin_save_criterion(
  p_event_id uuid,
  p_id uuid,
  p_name text,
  p_description text,
  p_max_marks numeric,
  p_display_order integer,
  p_is_active boolean,
  p_reason text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  perform public.assert_admin();
  perform public.apply_reason(p_reason);
  if p_id is null then
    insert into public.evaluation_criteria (event_id, name, description, max_marks, display_order, is_active)
    values (p_event_id, btrim(p_name), nullif(btrim(p_description), ''), p_max_marks,
            coalesce(p_display_order, 0), coalesce(p_is_active, true))
    returning id into v_id;
  else
    update public.evaluation_criteria
       set name = btrim(p_name), description = nullif(btrim(p_description), ''), max_marks = p_max_marks,
           display_order = coalesce(p_display_order, 0), is_active = coalesce(p_is_active, true)
     where id = p_id and event_id = p_event_id
    returning id into v_id;
    if v_id is null then
      raise exception 'NOT_FOUND';
    end if;
  end if;
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Participants
-- -----------------------------------------------------------------------------
create or replace function public.admin_set_event_participant(
  p_event_id uuid, p_participant_id uuid, p_active boolean, p_reason text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  perform public.assert_admin();
  perform public.apply_reason(p_reason);
  insert into public.event_participants (event_id, participant_id, is_active)
  values (p_event_id, p_participant_id, p_active)
  on conflict (event_id, participant_id) do update set is_active = excluded.is_active
  returning id into v_id;
  return v_id;
end;
$$;

create or replace function public.admin_set_participant_active(
  p_participant_id uuid, p_active boolean, p_reason text default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.assert_admin();
  perform public.apply_reason(p_reason);
  update public.participants set is_active = p_active where id = p_participant_id;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Participant import: all-or-nothing. Rows:
--   [{row, code, name, kind, group_code, event_code, affiliation, registration_no, notes}]
-- Re-importing an existing code with the same name links it (no duplicate);
-- an existing code with a different name is an error.
-- -----------------------------------------------------------------------------
create or replace function public.admin_import_participants(
  p_rows jsonb, p_source text default null, p_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  r jsonb;
  v_row integer;
  v_code text;
  v_name text;
  v_kind text;
  v_group uuid;
  v_event uuid;
  v_existing public.participants;
  v_pid uuid;
  v_link public.event_participants;
  v_errors jsonb := '[]'::jsonb;
  v_created integer := 0;
  v_linked integer := 0;
  v_already integer := 0;
begin
  perform public.assert_admin();
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'INVALID_REQUEST';
  end if;
  if jsonb_array_length(p_rows) > 5000 then
    raise exception 'IMPORT_TOO_LARGE';
  end if;
  perform public.apply_reason(p_reason);

  for r in select value from jsonb_array_elements(p_rows) loop
    v_row := coalesce((r ->> 'row')::integer, 0);
    v_code := upper(btrim(coalesce(r ->> 'code', '')));
    v_name := btrim(coalesce(r ->> 'name', ''));
    v_kind := lower(coalesce(nullif(btrim(r ->> 'kind'), ''), 'individual'));
    v_group := null;
    v_event := null;

    if v_code !~ '^[A-Z0-9][A-Z0-9._/-]{0,39}$' then
      v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'code', 'code', 'INVALID_CODE');
      continue;
    end if;
    if v_name = '' or char_length(v_name) > 200 then
      v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'name', 'code', 'INVALID_NAME');
      continue;
    end if;
    if v_kind not in ('individual', 'team') then
      v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'kind', 'code', 'INVALID_KIND');
      continue;
    end if;
    select id into v_group from public.groups where code = lower(btrim(coalesce(r ->> 'group_code', '')));
    if v_group is null then
      v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'group_code', 'code', 'UNKNOWN_GROUP');
      continue;
    end if;
    if coalesce(btrim(r ->> 'event_code'), '') <> '' then
      select id into v_event from public.events
       where group_id = v_group and code = lower(btrim(r ->> 'event_code'));
      if v_event is null then
        v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'event_code', 'code', 'UNKNOWN_EVENT');
        continue;
      end if;
    end if;

    select * into v_existing from public.participants where code = v_code;
    if found then
      if lower(btrim(v_existing.name)) <> lower(v_name) then
        v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'code', 'code', 'CODE_USED_BY_OTHER_NAME',
                                                   'existing_name', v_existing.name);
        continue;
      end if;
      if v_existing.group_id is distinct from v_group then
        v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'group_code', 'code', 'GROUP_MISMATCH');
        continue;
      end if;
      v_pid := v_existing.id;
    else
      insert into public.participants (code, name, kind, group_id, affiliation, registration_no, notes)
      values (v_code, v_name, v_kind::public.participant_kind, v_group,
              nullif(btrim(r ->> 'affiliation'), ''), nullif(btrim(r ->> 'registration_no'), ''),
              nullif(btrim(r ->> 'notes'), ''))
      returning id into v_pid;
      v_created := v_created + 1;
    end if;

    if v_event is not null then
      select * into v_link from public.event_participants where event_id = v_event and participant_id = v_pid;
      if not found then
        insert into public.event_participants (event_id, participant_id) values (v_event, v_pid);
        v_linked := v_linked + 1;
      elsif not v_link.is_active then
        update public.event_participants set is_active = true where id = v_link.id;
        v_linked := v_linked + 1;
      else
        v_already := v_already + 1;
      end if;
    end if;
  end loop;

  if jsonb_array_length(v_errors) > 0 then
    raise exception 'IMPORT_INVALID' using detail = v_errors::text;
  end if;

  perform public.log_audit(
    p_action => 'participants.imported', p_entity_type => 'participant_import',
    p_new => jsonb_build_object('created', v_created, 'linked', v_linked, 'already_linked', v_already,
                                'rows', jsonb_array_length(p_rows)),
    p_reason => p_reason, p_metadata => jsonb_build_object('source', p_source));

  return jsonb_build_object('created', v_created, 'linked', v_linked, 'already_linked', v_already,
                            'rows', jsonb_array_length(p_rows));
end;
$$;

-- -----------------------------------------------------------------------------
-- Service-role-only functions: called by trusted server code after it has
-- verified (with the caller's own session) that the caller is an admin.
-- -----------------------------------------------------------------------------
create or replace function public.service_create_profile(
  p_id uuid, p_username text, p_display_name text, p_role public.app_role, p_actor uuid
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  perform set_config('app.actor_id', coalesce(p_actor::text, ''), true);
  insert into public.profiles (id, username, display_name, role, created_by)
  values (p_id, lower(btrim(p_username)), btrim(p_display_name), p_role, p_actor);
end;
$$;

create or replace function public.service_update_profile(
  p_id uuid, p_display_name text, p_is_active boolean, p_actor uuid, p_reason text default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old public.profiles;
  v_event uuid;
begin
  perform set_config('app.actor_id', coalesce(p_actor::text, ''), true);
  perform public.apply_reason(p_reason);
  select * into v_old from public.profiles where id = p_id for update;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
  update public.profiles
     set display_name = coalesce(nullif(btrim(p_display_name), ''), display_name),
         is_active = coalesce(p_is_active, is_active)
   where id = p_id;
  if p_is_active is not null and p_is_active <> v_old.is_active then
    for v_event in select event_id from public.judge_assignments where judge_id = p_id and is_active loop
      perform public.invalidate_finalization_internal(
        v_event, format('Judge %s %s', v_old.username, case when p_is_active then 'activated' else 'deactivated' end));
    end loop;
  end if;
end;
$$;

create or replace function public.service_log_audit(
  p_action text, p_actor uuid, p_judge_id uuid default null, p_reason text default null,
  p_metadata jsonb default '{}', p_entity_type text default null, p_entity_id uuid default null
)
returns void
language plpgsql
security definer
set search_path = public, pg_temp
as $$
begin
  perform public.log_audit(
    p_action => p_action, p_entity_type => p_entity_type, p_entity_id => p_entity_id,
    p_reason => p_reason, p_judge_id => p_judge_id, p_metadata => p_metadata, p_actor_id => p_actor);
end;
$$;

-- -----------------------------------------------------------------------------
-- Realtime: admin dashboard listens to submission/request changes (RLS applies).
-- -----------------------------------------------------------------------------
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    alter publication supabase_realtime add table public.submissions, public.reopening_requests,
      public.correction_requests;
  end if;
end;
$$;

-- ==================== 20261022100600_privileges.sql ====================

-- =============================================================================
-- Function privileges: explicit allowlist.
--
-- Supabase's default privileges grant EXECUTE on new functions to anon and
-- authenticated. Internal helpers (transition_submission, log_audit,
-- invalidate_finalization_internal, service_* ...) must never be callable
-- through the Data API, so we revoke everything and re-grant only the
-- public RPC surface. Re-run this pattern in any future migration that adds
-- functions.
-- =============================================================================

alter default privileges in schema public revoke execute on functions from anon, authenticated, public;

revoke execute on all functions in schema public from anon, authenticated, public;

-- RLS helpers (used inside policies, evaluated as the calling role)
grant execute on function
  public.is_admin(),
  public.is_active_judge(),
  public.is_assigned(uuid),
  public.owns_submission(uuid),
  public.is_editable_status(public.submission_status)
to authenticated;

-- Judge RPCs (each re-checks ownership and state)
grant execute on function
  public.save_scores(uuid, jsonb),
  public.submit_submission(uuid, integer),
  public.request_reopening(uuid, text),
  public.respond_correction_request(uuid, text),
  public.submission_missing_count(uuid)
to authenticated;

-- Admin RPCs (each checks is_admin())
grant execute on function
  public.event_has_scores(uuid),
  public.resolve_reopening_request(uuid, boolean, text),
  public.admin_reopen_submission(uuid, text),
  public.create_correction_request(uuid, uuid, uuid[], text, boolean),
  public.resolve_correction_request(uuid, text, boolean),
  public.admin_set_score(uuid, uuid, uuid, numeric, text),
  public.get_event_results(uuid),
  public.resolve_tie(uuid, uuid[], jsonb, text, uuid[]),
  public.finalize_event_results(uuid),
  public.unfinalize_event_results(uuid, text),
  public.admin_event_progress(),
  public.admin_set_assignment(uuid, uuid, boolean, text),
  public.admin_save_event(uuid, uuid, text, text, text, text, smallint, integer, boolean, text),
  public.admin_save_criterion(uuid, uuid, text, text, numeric, integer, boolean, text),
  public.admin_set_event_participant(uuid, uuid, boolean, text),
  public.admin_set_participant_active(uuid, boolean, text),
  public.admin_import_participants(jsonb, text, text)
to authenticated;

-- Trusted server code only
grant execute on function
  public.service_create_profile(uuid, text, text, public.app_role, uuid),
  public.service_update_profile(uuid, text, boolean, uuid, text),
  public.service_log_audit(text, uuid, uuid, text, jsonb, text, uuid)
to service_role;

-- Report generation and email delivery are audited too.
create trigger report_records_audit after insert or update on public.report_records
  for each row execute function public.audit_row_change();

-- ==================== 20261023100000_accounts_settings_reset.sql ====================

-- =============================================================================
-- DLBTS KN: event name/year settings, SQL account management, yearly reset.
-- =============================================================================

-- -----------------------------------------------------------------------------
-- Settings: the title shown everywhere is "<app_name> <event_year>".
-- -----------------------------------------------------------------------------
insert into public.app_settings (key, value) values
  ('app_name', '"DLBTS KN"'),
  ('event_year', '2026')
on conflict (key) do nothing;

update public.app_settings set value = '"DLBTS KN 2026"' where key = 'app_title' and value = '"Event Judging"';

-- -----------------------------------------------------------------------------
-- Accounts created directly in SQL (Supabase SQL editor, runs as postgres).
-- Passwords are hashed with bcrypt exactly like Supabase Auth does.
-- These functions are NOT callable through the API (no grants).
--
--   select public.create_account('judge01grp1sloka', 'pwd01grp1sloka', 'Group 1 Sloka Judge 1', 'judge');
--   select public.set_account_password('judge01grp1sloka', 'new-password');
--
-- p_domain must equal the app's AUTH_EMAIL_DOMAIN (default judges.invalid).
-- -----------------------------------------------------------------------------
create or replace function public.create_account(
  p_username text,
  p_password text,
  p_display_name text,
  p_role public.app_role default 'judge',
  p_domain text default 'judges.invalid'
)
returns uuid
language plpgsql
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_user text := lower(btrim(p_username));
  v_email text;
  v_id uuid;
begin
  if v_user !~ '^[a-z0-9][a-z0-9._-]{2,49}$' then
    raise exception 'INVALID_USERNAME' using detail = p_username;
  end if;
  if p_password is null or char_length(p_password) < 6 then
    raise exception 'PASSWORD_TOO_SHORT' using detail = p_username;
  end if;
  v_email := v_user || '@' || lower(btrim(p_domain));

  -- Idempotent: an existing account is left unchanged (use set_account_password to change it).
  select id into v_id from public.profiles where username = v_user;
  if v_id is not null then
    return v_id;
  end if;
  select id into v_id from auth.users where email = v_email;

  if v_id is null then
    v_id := gen_random_uuid();
    insert into auth.users (
      instance_id, id, aud, role, email, encrypted_password, email_confirmed_at,
      raw_app_meta_data, raw_user_meta_data, created_at, updated_at,
      confirmation_token, recovery_token, email_change_token_new, email_change
    ) values (
      '00000000-0000-0000-0000-000000000000', v_id, 'authenticated', 'authenticated', v_email,
      crypt(p_password, gen_salt('bf')), now(),
      '{"provider": "email", "providers": ["email"]}', jsonb_build_object('username', v_user), now(), now(),
      '', '', '', ''
    );
    insert into auth.identities (id, user_id, provider_id, identity_data, provider, last_sign_in_at, created_at, updated_at)
    values (
      gen_random_uuid(), v_id, v_id::text,
      jsonb_build_object('sub', v_id::text, 'email', v_email, 'email_verified', true),
      'email', now(), now(), now()
    );
  end if;

  insert into public.profiles (id, username, display_name, role)
  values (v_id, v_user, btrim(p_display_name), p_role);
  return v_id;
end;
$$;

create or replace function public.set_account_password(p_username text, p_password text)
returns void
language plpgsql
security definer
set search_path = public, extensions, pg_temp
as $$
declare
  v_id uuid;
begin
  if p_password is null or char_length(p_password) < 6 then
    raise exception 'PASSWORD_TOO_SHORT';
  end if;
  select id into v_id from public.profiles where username = lower(btrim(p_username));
  if v_id is null then
    raise exception 'NOT_FOUND' using detail = p_username;
  end if;
  update auth.users set encrypted_password = crypt(p_password, gen_salt('bf')), updated_at = now() where id = v_id;
  perform public.log_audit(p_action => 'account.password_set_sql', p_entity_type => 'profile', p_entity_id => v_id, p_judge_id => v_id);
end;
$$;

revoke execute on function public.create_account(text, text, text, public.app_role, text) from public, anon, authenticated, service_role;
revoke execute on function public.set_account_password(text, text) from public, anon, authenticated, service_role;

-- -----------------------------------------------------------------------------
-- Yearly reset. Keeps groups, events, criteria, judge accounts, passwords,
-- assignments, settings and the audit log. Deletes participants and every
-- mark, submission state, request, tie decision, finalization and report record.
-- The append-only protections allow deletes only while app.reset_mode is on,
-- which can only be set inside this function (not reachable via the API).
-- -----------------------------------------------------------------------------
create or replace function public.in_reset_mode()
returns boolean
language sql
stable
set search_path = public, pg_temp
as $$
  select coalesce(current_setting('app.reset_mode', true), '') = 'on';
$$;

create or replace function public.forbid_modification()
returns trigger
language plpgsql
set search_path = public, pg_temp
as $$
begin
  if tg_op = 'DELETE' and tg_table_name <> 'audit_logs' and public.in_reset_mode() then
    return old;
  end if;
  raise exception 'APPEND_ONLY' using detail = format('%s is append-only', tg_table_name);
end;
$$;

create or replace function public.validate_score()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
  v_crit public.evaluation_criteria;
  v_precision smallint;
begin
  if tg_op = 'DELETE' then
    if public.in_reset_mode() then
      return old;
    end if;
    raise exception 'SCORE_DELETE_FORBIDDEN';
  end if;
  if tg_op = 'UPDATE' and (new.submission_id <> old.submission_id
       or new.participant_id <> old.participant_id
       or new.criterion_id <> old.criterion_id) then
    raise exception 'SCORE_KEY_IMMUTABLE';
  end if;

  select * into v_sub from public.submissions where id = new.submission_id;
  select * into v_crit from public.evaluation_criteria where id = new.criterion_id;
  if v_crit.event_id is distinct from v_sub.event_id then
    raise exception 'CRITERION_NOT_IN_EVENT';
  end if;
  if not exists (select 1 from public.event_participants
                 where event_id = v_sub.event_id and participant_id = new.participant_id) then
    raise exception 'PARTICIPANT_NOT_IN_EVENT';
  end if;

  if not public.is_editable_status(v_sub.status)
     and coalesce(current_setting('app.admin_override', true), '') <> 'on' then
    raise exception 'SUBMISSION_LOCKED';
  end if;

  if new.value is not null then
    select score_precision into v_precision from public.events where id = v_sub.event_id;
    if new.value < 0 or new.value > v_crit.max_marks then
      raise exception 'OUT_OF_RANGE';
    end if;
    if new.value <> round(new.value, v_precision) then
      raise exception 'PRECISION';
    end if;
  end if;

  if tg_op = 'UPDATE' then
    new.version := case when new.value is distinct from old.value then old.version + 1 else old.version end;
  else
    new.version := 1;
  end if;
  return new;
end;
$$;

-- Row-level audit is skipped during a reset (one summary entry is written instead).
create or replace function public.audit_row_change()
returns trigger
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_old jsonb;
  v_new jsonb;
  v_row jsonb;
begin
  if public.in_reset_mode() then
    return coalesce(new, old);
  end if;
  if tg_op in ('UPDATE', 'DELETE') then v_old := to_jsonb(old); end if;
  if tg_op in ('INSERT', 'UPDATE') then v_new := to_jsonb(new); end if;
  if tg_op = 'UPDATE' and (v_old - 'updated_at') = (v_new - 'updated_at') then
    return new;
  end if;
  v_row := coalesce(v_new, v_old);

  perform public.log_audit(
    p_action => tg_table_name || '.' || lower(tg_op),
    p_entity_type => tg_table_name,
    p_entity_id => case when v_row ? 'id' then (v_row ->> 'id')::uuid end,
    p_old => v_old,
    p_new => v_new,
    p_reason => public.current_reason(),
    p_event_id => case when tg_table_name = 'events' then (v_row ->> 'id')::uuid
                       else (v_row ->> 'event_id')::uuid end,
    p_group_id => case when tg_table_name = 'groups' then (v_row ->> 'id')::uuid
                       else (v_row ->> 'group_id')::uuid end,
    p_participant_id => case when tg_table_name = 'participants' then (v_row ->> 'id')::uuid
                             else (v_row ->> 'participant_id')::uuid end,
    p_judge_id => case when tg_table_name = 'profiles' then (v_row ->> 'id')::uuid
                       else (v_row ->> 'judge_id')::uuid end
  );
  return coalesce(new, old);
end;
$$;

create or replace function public.admin_reset_event_data(p_confirm text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_counts jsonb;
begin
  perform public.assert_admin();
  if p_confirm is distinct from 'RESET' then
    raise exception 'CONFIRMATION_REQUIRED';
  end if;

  select jsonb_build_object(
    'participants', (select count(*) from public.participants),
    'marks', (select count(*) from public.criterion_scores),
    'submitted', (select count(*) from public.submissions where status in ('submitted', 'resubmitted')),
    'finalized_events', (select count(*) from public.result_finalizations where status = 'active')
  ) into v_counts;

  perform set_config('app.reset_mode', 'on', true);
  delete from public.result_finalizations where true;
  delete from public.tie_resolutions where true;
  delete from public.report_records where true;
  delete from public.correction_requests where true;
  delete from public.reopening_requests where true;
  delete from public.submission_rounds where true;
  delete from public.submission_transitions where true;
  delete from public.score_history where true;
  delete from public.criterion_scores where true;
  delete from public.event_participants where true;
  delete from public.participants where true;
  update public.submissions
     set status = 'not_started', version = 0, round = 0,
         submitted_at = null, submitted_by = null, last_saved_at = null
   where true;
  perform set_config('app.reset_mode', '', true);

  perform public.log_audit(p_action => 'system.reset', p_entity_type => 'system', p_metadata => v_counts,
                           p_reason => 'Reset all participants and marks for a new year');
  return v_counts;
end;
$$;

revoke execute on function public.in_reset_mode() from public, anon;
grant execute on function public.in_reset_mode() to authenticated;
grant execute on function public.admin_reset_event_data(text) to authenticated;

-- ==================== 20261026100000_judge_features.sql ====================

-- =============================================================================
-- Judge features (2026-10-26)
--   * events.venue                      room / location shown to judges
--   * participants.members              team member names (team events)
--   * participants.memento_*            memento given tracking (shared by all judges)
--   * participant_remarks               judge feedback per participant
--   * participant_requests              judge -> admin add / change / remove requests
--   * event_participant_context()       other events + memento for an event's participants
--   * event_tie_alerts()                provisional ties among the top 3 during judging
-- Safe to run more than once.
-- =============================================================================

alter table public.events add column if not exists venue text;
alter table public.participants add column if not exists members text;
alter table public.participants add column if not exists memento_given boolean not null default false;
alter table public.participants add column if not exists memento_given_at timestamptz;
alter table public.participants add column if not exists memento_given_by uuid references public.profiles (id);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'events_venue_len') then
    alter table public.events add constraint events_venue_len check (char_length(venue) <= 120);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'participants_members_len') then
    alter table public.participants add constraint participants_members_len check (char_length(members) <= 1000);
  end if;
end;
$$;

-- -----------------------------------------------------------------------------
-- Judge remarks / feedback
-- -----------------------------------------------------------------------------
create table if not exists public.participant_remarks (
  id uuid primary key default gen_random_uuid(),
  submission_id uuid not null references public.submissions (id) on delete restrict,
  participant_id uuid not null references public.participants (id) on delete restrict,
  remark text not null default '' check (char_length(remark) <= 2000),
  updated_by uuid references public.profiles (id),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (submission_id, participant_id)
);
create index if not exists participant_remarks_participant_idx on public.participant_remarks (participant_id);
drop trigger if exists participant_remarks_updated_at on public.participant_remarks;
create trigger participant_remarks_updated_at before update on public.participant_remarks
  for each row execute function public.set_updated_at();

alter table public.participant_remarks enable row level security;
drop policy if exists participant_remarks_read on public.participant_remarks;
create policy participant_remarks_read on public.participant_remarks for select to authenticated
  using ((select public.is_admin()) or public.owns_submission(submission_id));
revoke all on public.participant_remarks from anon;
grant select on public.participant_remarks to authenticated;

-- -----------------------------------------------------------------------------
-- Participant requests (judge -> admin)
-- -----------------------------------------------------------------------------
create table if not exists public.participant_requests (
  id uuid primary key default gen_random_uuid(),
  event_id uuid not null references public.events (id) on delete restrict,
  requested_by uuid not null references public.profiles (id),
  request_type text not null check (request_type in ('add', 'change', 'remove')),
  participant_id uuid references public.participants (id) on delete set null,
  name text check (char_length(name) <= 200),
  details text not null check (char_length(btrim(details)) between 3 and 2000),
  status public.request_status not null default 'pending',
  created_participant_id uuid references public.participants (id) on delete set null,
  resolved_by uuid references public.profiles (id),
  resolved_at timestamptz,
  resolution_note text check (char_length(resolution_note) <= 2000),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index if not exists participant_requests_event_idx on public.participant_requests (event_id);
drop trigger if exists participant_requests_updated_at on public.participant_requests;
create trigger participant_requests_updated_at before update on public.participant_requests
  for each row execute function public.set_updated_at();

alter table public.participant_requests enable row level security;
drop policy if exists participant_requests_read on public.participant_requests;
create policy participant_requests_read on public.participant_requests for select to authenticated
  using ((select public.is_admin()) or (requested_by = (select auth.uid()) and public.is_assigned(event_id)));
revoke all on public.participant_requests from anon;
grant select on public.participant_requests to authenticated;

-- -----------------------------------------------------------------------------
-- Remarks: judges save while their submission is editable
-- -----------------------------------------------------------------------------
create or replace function public.save_remark(p_submission_id uuid, p_participant_id uuid, p_remark text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_sub public.submissions;
  v_row public.participant_remarks;
begin
  if char_length(coalesce(p_remark, '')) > 2000 then
    raise exception 'INVALID_REQUEST';
  end if;
  v_sub := public.lock_own_submission(p_submission_id);
  if not public.is_editable_status(v_sub.status) then
    raise exception 'SUBMISSION_LOCKED';
  end if;
  if not exists (
    select 1 from public.event_participants ep
    where ep.event_id = v_sub.event_id and ep.participant_id = p_participant_id and ep.is_active
  ) then
    raise exception 'PARTICIPANT_NOT_IN_EVENT';
  end if;
  insert into public.participant_remarks (submission_id, participant_id, remark, updated_by)
  values (v_sub.id, p_participant_id, btrim(coalesce(p_remark, '')), auth.uid())
  on conflict (submission_id, participant_id)
  do update set remark = excluded.remark, updated_by = excluded.updated_by
  returning * into v_row;
  return jsonb_build_object('participant_id', p_participant_id, 'remark', v_row.remark, 'updated_at', v_row.updated_at);
end;
$$;

-- -----------------------------------------------------------------------------
-- Memento: any judge assigned to one of the participant's events (or an admin)
-- -----------------------------------------------------------------------------
create or replace function public.set_memento(p_participant_id uuid, p_given boolean)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_p public.participants;
begin
  if not (public.is_admin() or exists (
    select 1 from public.event_participants ep
    where ep.participant_id = p_participant_id and ep.is_active and public.is_assigned(ep.event_id)
  )) then
    raise exception 'FORBIDDEN';
  end if;
  update public.participants
     set memento_given = coalesce(p_given, false),
         memento_given_at = case when p_given then now() end,
         memento_given_by = case when p_given then auth.uid() end
   where id = p_participant_id
  returning * into v_p;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
  return jsonb_build_object(
    'given', v_p.memento_given,
    'at', v_p.memento_given_at,
    'by', (select display_name from public.profiles where id = v_p.memento_given_by));
end;
$$;

-- -----------------------------------------------------------------------------
-- Other events + memento for every participant of an event (judge or admin)
-- -----------------------------------------------------------------------------
create or replace function public.event_participant_context(p_event_id uuid)
returns table (
  participant_id uuid,
  other_events jsonb,
  memento_given boolean,
  memento_given_at timestamptz,
  memento_given_by_name text
)
language sql
stable
security definer
set search_path = public, pg_temp
as $$
  select p.id,
         coalesce((
           select jsonb_agg(jsonb_build_object('event_id', e.id, 'name', e.name, 'group', g.name, 'venue', e.venue)
                            order by g.display_order, e.display_order, e.name)
           from public.event_participants ep2
           join public.events e on e.id = ep2.event_id and e.is_active
           join public.groups g on g.id = e.group_id
           where ep2.participant_id = p.id and ep2.is_active and ep2.event_id <> p_event_id
         ), '[]'::jsonb),
         p.memento_given, p.memento_given_at, pr.display_name
  from public.event_participants ep
  join public.participants p on p.id = ep.participant_id and p.is_active
  left join public.profiles pr on pr.id = p.memento_given_by
  where ep.event_id = p_event_id and ep.is_active
    and (public.is_admin() or public.is_assigned(p_event_id));
$$;

-- -----------------------------------------------------------------------------
-- Provisional ties during judging. Considers participants whose marks are
-- complete from every required judge, ranks them by combined score and returns
-- groups that share a combined score within the top 3 places. Scores are NOT
-- returned, so judges never see each other's marks.
-- -----------------------------------------------------------------------------
create or replace function public.event_tie_alerts(p_event_id uuid)
returns jsonb
language plpgsql
stable
security definer
set search_path = public, pg_temp
as $$
declare
  v_result jsonb;
begin
  if not (public.is_admin() or public.is_assigned(p_event_id)) then
    raise exception 'FORBIDDEN';
  end if;

  with req as (
    select s.id as submission_id
    from public.judge_assignments a
    join public.profiles pr on pr.id = a.judge_id and pr.is_active and pr.role = 'judge'
    join public.submissions s on s.event_id = a.event_id and s.judge_id = a.judge_id
    where a.event_id = p_event_id and a.is_active
  ),
  crit as (
    select id from public.evaluation_criteria where event_id = p_event_id and is_active
  ),
  ep as (
    select p.id, p.name, p.code
    from public.event_participants e
    join public.participants p on p.id = e.participant_id and p.is_active
    where e.event_id = p_event_id and e.is_active
  ),
  marks as (
    select cs.participant_id, count(cs.value) as filled, sum(cs.value) as total
    from public.criterion_scores cs
    join req on req.submission_id = cs.submission_id
    join crit on crit.id = cs.criterion_id
    group by cs.participant_id
  ),
  complete as (
    select ep.id, ep.name, ep.code, m.total
    from ep join marks m on m.participant_id = ep.id
    where m.filled = (select count(*) from req) * (select count(*) from crit)
      and (select count(*) from req) > 0 and (select count(*) from crit) > 0
  ),
  ranked as (
    select c.*, rank() over (order by c.total desc) as rnk, count(*) over (partition by c.total) as n
    from complete c
  ),
  groups_ as (
    select min(rnk) as place,
           jsonb_agg(jsonb_build_object('participant_id', id, 'name', name, 'code', code) order by code) as participants
    from ranked
    where n > 1
    group by total
    having min(rnk) <= 3
  )
  select coalesce(jsonb_agg(jsonb_build_object('place', place, 'participants', participants) order by place), '[]'::jsonb)
    into v_result
    from groups_;
  return v_result;
end;
$$;

-- -----------------------------------------------------------------------------
-- Participant requests
-- -----------------------------------------------------------------------------
create or replace function public.request_participant_change(
  p_event_id uuid,
  p_type text,
  p_participant_id uuid,
  p_name text,
  p_details text
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  if not public.is_assigned(p_event_id) then
    raise exception 'NOT_FOUND';
  end if;
  if p_type not in ('add', 'change', 'remove') then
    raise exception 'INVALID_REQUEST';
  end if;
  if p_details is null or char_length(btrim(p_details)) < 3 then
    raise exception 'REASON_REQUIRED';
  end if;
  if p_type = 'add' and coalesce(btrim(p_name), '') = '' then
    raise exception 'INVALID_REQUEST';
  end if;
  if p_type <> 'add' and not exists (
    select 1 from public.event_participants where event_id = p_event_id and participant_id = p_participant_id
  ) then
    raise exception 'PARTICIPANT_NOT_IN_EVENT';
  end if;
  insert into public.participant_requests (event_id, requested_by, request_type, participant_id, name, details)
  values (p_event_id, auth.uid(), p_type, case when p_type = 'add' then null else p_participant_id end,
          nullif(btrim(p_name), ''), btrim(p_details))
  returning id into v_id;
  perform public.log_audit(
    p_action => 'participant_request.created', p_entity_type => 'participant_request', p_entity_id => v_id,
    p_new => jsonb_build_object('type', p_type, 'name', p_name), p_reason => p_details,
    p_event_id => p_event_id, p_participant_id => p_participant_id, p_judge_id => auth.uid(), p_request_id => v_id);
  return v_id;
end;
$$;

-- Admin decision. For "add" + approve, creates the participant and adds it to the event.
-- For "remove" + approve, removes the participant from the event.
-- For "change" + approve, the admin makes the edit themselves; this records the decision.
create or replace function public.resolve_participant_request(
  p_request_id uuid,
  p_approve boolean,
  p_note text,
  p_code text default null,
  p_name text default null,
  p_kind text default 'individual',
  p_affiliation text default null,
  p_members text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_req public.participant_requests;
  v_group uuid;
  v_pid uuid;
  v_reason text;
begin
  perform public.assert_admin();
  select * into v_req from public.participant_requests where id = p_request_id for update;
  if not found then
    raise exception 'NOT_FOUND';
  end if;
  if v_req.status <> 'pending' then
    raise exception 'INVALID_STATE';
  end if;
  v_reason := 'Judge request: ' || v_req.details;

  if p_approve and v_req.request_type = 'add' then
    if coalesce(btrim(p_code), '') = '' or coalesce(btrim(p_name), '') = '' then
      raise exception 'INVALID_REQUEST';
    end if;
    select group_id into v_group from public.events where id = v_req.event_id;
    insert into public.participants (code, name, kind, group_id, affiliation, members)
    values (upper(btrim(p_code)), btrim(p_name),
            (case when p_kind = 'team' then 'team' else 'individual' end)::public.participant_kind,
            v_group, nullif(btrim(p_affiliation), ''), nullif(btrim(p_members), ''))
    returning id into v_pid;
    perform public.admin_set_event_participant(v_req.event_id, v_pid, true, v_reason);
  elsif p_approve and v_req.request_type = 'remove' and v_req.participant_id is not null then
    perform public.admin_set_event_participant(v_req.event_id, v_req.participant_id, false, v_reason);
  end if;

  update public.participant_requests
     set status = case when p_approve then 'approved'::public.request_status else 'rejected'::public.request_status end,
         resolved_by = auth.uid(), resolved_at = now(),
         resolution_note = nullif(btrim(p_note), ''),
         created_participant_id = v_pid
   where id = v_req.id;

  perform public.log_audit(
    p_action => case when p_approve then 'participant_request.approved' else 'participant_request.rejected' end,
    p_entity_type => 'participant_request', p_entity_id => v_req.id, p_reason => coalesce(nullif(btrim(p_note), ''), v_req.details),
    p_event_id => v_req.event_id, p_participant_id => coalesce(v_pid, v_req.participant_id),
    p_judge_id => v_req.requested_by, p_request_id => v_req.id);
  return v_pid;
end;
$$;

-- -----------------------------------------------------------------------------
-- Events: venue
-- -----------------------------------------------------------------------------
drop function if exists public.admin_save_event(uuid, uuid, text, text, text, text, smallint, integer, boolean, text);
create or replace function public.admin_save_event(
  p_id uuid,
  p_group_id uuid,
  p_code text,
  p_name text,
  p_description text,
  p_instructions text,
  p_score_precision smallint,
  p_display_order integer,
  p_is_active boolean,
  p_reason text default null,
  p_venue text default null
)
returns uuid
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_id uuid;
begin
  perform public.assert_admin();
  perform public.apply_reason(p_reason);
  if p_id is null then
    insert into public.events (group_id, code, name, description, instructions, score_precision, display_order, is_active, venue)
    values (p_group_id, lower(btrim(p_code)), btrim(p_name), nullif(btrim(p_description), ''),
            nullif(btrim(p_instructions), ''), p_score_precision, coalesce(p_display_order, 0), coalesce(p_is_active, true),
            nullif(btrim(p_venue), ''))
    returning id into v_id;
  else
    update public.events
       set group_id = p_group_id, code = lower(btrim(p_code)), name = btrim(p_name),
           description = nullif(btrim(p_description), ''), instructions = nullif(btrim(p_instructions), ''),
           score_precision = p_score_precision, display_order = coalesce(p_display_order, 0),
           is_active = coalesce(p_is_active, true), venue = nullif(btrim(p_venue), '')
     where id = p_id
    returning id into v_id;
    if v_id is null then
      raise exception 'NOT_FOUND';
    end if;
  end if;
  return v_id;
end;
$$;

-- -----------------------------------------------------------------------------
-- Import: optional "members" column for teams
-- -----------------------------------------------------------------------------
create or replace function public.admin_import_participants(
  p_rows jsonb, p_source text default null, p_reason text default null
)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  r jsonb;
  v_row integer;
  v_code text;
  v_name text;
  v_kind text;
  v_group uuid;
  v_event uuid;
  v_existing public.participants;
  v_pid uuid;
  v_link public.event_participants;
  v_errors jsonb := '[]'::jsonb;
  v_created integer := 0;
  v_linked integer := 0;
  v_already integer := 0;
begin
  perform public.assert_admin();
  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'INVALID_REQUEST';
  end if;
  if jsonb_array_length(p_rows) > 5000 then
    raise exception 'IMPORT_TOO_LARGE';
  end if;
  perform public.apply_reason(p_reason);

  for r in select value from jsonb_array_elements(p_rows) loop
    v_row := coalesce((r ->> 'row')::integer, 0);
    v_code := upper(btrim(coalesce(r ->> 'code', '')));
    v_name := btrim(coalesce(r ->> 'name', ''));
    v_kind := lower(coalesce(nullif(btrim(r ->> 'kind'), ''), 'individual'));
    v_group := null;
    v_event := null;

    if v_code !~ '^[A-Z0-9][A-Z0-9._/-]{0,39}$' then
      v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'code', 'code', 'INVALID_CODE');
      continue;
    end if;
    if v_name = '' or char_length(v_name) > 200 then
      v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'name', 'code', 'INVALID_NAME');
      continue;
    end if;
    if v_kind not in ('individual', 'team') then
      v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'kind', 'code', 'INVALID_KIND');
      continue;
    end if;
    select id into v_group from public.groups where code = lower(btrim(coalesce(r ->> 'group_code', '')));
    if v_group is null then
      v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'group_code', 'code', 'UNKNOWN_GROUP');
      continue;
    end if;
    if coalesce(btrim(r ->> 'event_code'), '') <> '' then
      select id into v_event from public.events
       where group_id = v_group and code = lower(btrim(r ->> 'event_code'));
      if v_event is null then
        v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'event_code', 'code', 'UNKNOWN_EVENT');
        continue;
      end if;
    end if;

    select * into v_existing from public.participants where code = v_code;
    if found then
      if lower(btrim(v_existing.name)) <> lower(v_name) then
        v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'code', 'code', 'CODE_USED_BY_OTHER_NAME',
                                                   'existing_name', v_existing.name);
        continue;
      end if;
      if v_existing.group_id is distinct from v_group then
        v_errors := v_errors || jsonb_build_object('row', v_row, 'field', 'group_code', 'code', 'GROUP_MISMATCH');
        continue;
      end if;
      v_pid := v_existing.id;
    else
      insert into public.participants (code, name, kind, group_id, affiliation, registration_no, notes, members)
      values (v_code, v_name, v_kind::public.participant_kind, v_group,
              nullif(btrim(r ->> 'affiliation'), ''), nullif(btrim(r ->> 'registration_no'), ''),
              nullif(btrim(r ->> 'notes'), ''), nullif(btrim(r ->> 'members'), ''))
      returning id into v_pid;
      v_created := v_created + 1;
    end if;

    if v_event is not null then
      select * into v_link from public.event_participants where event_id = v_event and participant_id = v_pid;
      if not found then
        insert into public.event_participants (event_id, participant_id) values (v_event, v_pid);
        v_linked := v_linked + 1;
      elsif not v_link.is_active then
        update public.event_participants set is_active = true where id = v_link.id;
        v_linked := v_linked + 1;
      else
        v_already := v_already + 1;
      end if;
    end if;
  end loop;

  if jsonb_array_length(v_errors) > 0 then
    raise exception 'IMPORT_INVALID' using detail = v_errors::text;
  end if;

  perform public.log_audit(
    p_action => 'participants.imported', p_entity_type => 'participant_import',
    p_new => jsonb_build_object('created', v_created, 'linked', v_linked, 'already_linked', v_already,
                                'rows', jsonb_array_length(p_rows)),
    p_reason => p_reason, p_metadata => jsonb_build_object('source', p_source));

  return jsonb_build_object('created', v_created, 'linked', v_linked, 'already_linked', v_already,
                            'rows', jsonb_array_length(p_rows));
end;
$$;

-- -----------------------------------------------------------------------------
-- Yearly reset also clears remarks and participant requests
-- -----------------------------------------------------------------------------
create or replace function public.admin_reset_event_data(p_confirm text)
returns jsonb
language plpgsql
security definer
set search_path = public, pg_temp
as $$
declare
  v_counts jsonb;
begin
  perform public.assert_admin();
  if p_confirm is distinct from 'RESET' then
    raise exception 'CONFIRMATION_REQUIRED';
  end if;

  select jsonb_build_object(
    'participants', (select count(*) from public.participants),
    'marks', (select count(*) from public.criterion_scores),
    'submitted', (select count(*) from public.submissions where status in ('submitted', 'resubmitted')),
    'finalized_events', (select count(*) from public.result_finalizations where status = 'active')
  ) into v_counts;

  perform set_config('app.reset_mode', 'on', true);
  delete from public.result_finalizations where true;
  delete from public.tie_resolutions where true;
  delete from public.report_records where true;
  delete from public.correction_requests where true;
  delete from public.reopening_requests where true;
  delete from public.participant_requests where true;
  delete from public.participant_remarks where true;
  delete from public.submission_rounds where true;
  delete from public.submission_transitions where true;
  delete from public.score_history where true;
  delete from public.criterion_scores where true;
  delete from public.event_participants where true;
  delete from public.participants where true;
  update public.submissions
     set status = 'not_started', version = 0, round = 0,
         submitted_at = null, submitted_by = null, last_saved_at = null
   where true;
  perform set_config('app.reset_mode', '', true);

  perform public.log_audit(p_action => 'system.reset', p_entity_type => 'system', p_metadata => v_counts,
                           p_reason => 'Reset all participants and marks for a new year');
  return v_counts;
end;
$$;

-- -----------------------------------------------------------------------------
-- Privileges for new / changed functions (EXECUTE is not granted by default)
-- -----------------------------------------------------------------------------
revoke execute on function
  public.save_remark(uuid, uuid, text),
  public.set_memento(uuid, boolean),
  public.event_participant_context(uuid),
  public.event_tie_alerts(uuid),
  public.request_participant_change(uuid, text, uuid, text, text),
  public.resolve_participant_request(uuid, boolean, text, text, text, text, text, text),
  public.admin_save_event(uuid, uuid, text, text, text, text, smallint, integer, boolean, text, text)
from public, anon;

grant execute on function
  public.save_remark(uuid, uuid, text),
  public.set_memento(uuid, boolean),
  public.event_participant_context(uuid),
  public.event_tie_alerts(uuid),
  public.request_participant_change(uuid, text, uuid, text, text),
  public.resolve_participant_request(uuid, boolean, text, text, text, text, text, text),
  public.admin_save_event(uuid, uuid, text, text, text, text, smallint, integer, boolean, text, text),
  public.admin_import_participants(jsonb, text, text),
  public.admin_reset_event_data(text)
to authenticated;

-- Admin dashboard gets live updates for new participant requests.
do $$
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables
                     where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'participant_requests') then
    alter publication supabase_realtime add table public.participant_requests;
  end if;
end;
$$;
